// v31 — ATENDER CLIENTE ENCAMINHADO PELO DONO
// O dono escreve ao bot: "atende 74 99999-8888, Maria: soleira de 1,20 por 13 sem acabamento no Preto São Gabriel".
// O bot lê número, nome, tipo, pedra, medidas e acabamento, calcula na hora com a tabela do app e manda o valor ao cliente
// com os botões "Confirmar pedido" / "Tenho uma dúvida". Daí em diante é o funil normal (confirmação, PDF pelo app, Pix, entrega).
// Janela de 24 h da Meta: se o cliente não falou com o número do bot nas últimas 24 h, o 1º envio usa o modelo
// TEMPLATE_ORCAMENTO (Utilidade, pt_BR, 3 variáveis: {{1}} nome, {{2}} pedido, {{3}} valor; 2 botões de resposta rápida:
// "Confirmar pedido" e "Tenho uma dúvida"). Sem o modelo, o bot devolve ao dono o texto pronto para ele mesmo encaminhar.
// ══════════════════════════════════════════════════════════════════════
const NAO_NOME_ENC = new Set(['preto', 'preta', 'branco', 'branca', 'cinza', 'verde', 'sao', 'são', 'soleira', 'soleiras', 'peitoril', 'peitoris', 'granito', 'marmore', 'mármore', 'pedra', 'cliente', 'sem', 'com', 'acabamento', 'bom', 'boa', 'oi', 'ola', 'olá', 'atende', 'atenda', 'manda', 'passa', 'orçamento', 'orcamento', 'valor', 'ele', 'ela', 'amarelo', 'vermelho', 'marrom', 'travertino', 'quartzo', 'ocre', 'bege', 'absoluto', 'gabriel', 'itaúnas', 'itaunas', 'ubatuba', 'andorinha']);
function numeroMeta(d) { return /^55\d{2}9\d{8}$/.test(d) ? d.slice(0, 4) + d.slice(5) : d; } // a Meta entrega celular BR sem o 9
function variantesNumero(d) { const a = normalizarBR(d), b = numeroMeta(a); return [...new Set([a, b])]; }
function nomeNoTexto(t) {
  const m1 = String(t).match(/\bnome\s*[:=]\s*([A-Za-zÀ-ÿ]+(?:\s+[A-Za-zÀ-ÿ]+)?)/i);
  if (m1) return m1[1];
  const re = /(?:^|[\s,;:(])(?:(?:o|a|do|da|pro|pra|para o|para a|cliente)\s+)?([A-ZÀ-Ý][a-zà-ÿ]{2,}(?:\s+(?:de |da |do |dos )?[A-ZÀ-Ý][a-zà-ÿ]{2,})?)/g;
  let m;
  while ((m = re.exec(String(t)))) {
    const w = m[1].split(/\s+/);
    if (NAO_NOME_ENC.has(w[0].toLowerCase())) continue;
    return w.filter(x => !NAO_NOME_ENC.has(x.toLowerCase())).join(' ');
  }
  return '';
}
