// ── Etapa 63: consulta ao histórico completo do app (clientes e orçamentos, inclusive antigos e arquivados) ──
const HIST_KEY = 'cfg:historico';
async function lerHistorico(env) {
  try {
    const h = JSON.parse((await env.HR_KV.get(HIST_KEY)) || 'null');
    return h && Array.isArray(h.clientes) && Array.isArray(h.orcamentos) ? h : null;
  } catch (_) { return null; }
}
// Aceita só os campos conhecidos, corta tamanhos e remove repetidos (mesmo id, ou mesmo cliente+data+valor+projeto; mesmo nome+telefone)
function limparHistorico(b) {
  const t = (v, n) => String(v == null ? '' : v).replace(/\s+/g, ' ').trim().slice(0, n);
  const n = v => { v = Number(v); return Number.isFinite(v) ? Math.round(v * 100) / 100 : 0; };
  const vistosC = new Set(), clientes = [];
  for (const c of b.clientes.slice(0, 20000)) {
    if (!c || !t(c.nome, 60)) continue;
    const o = { nome: t(c.nome, 60), tel: t(c.tel, 20), cidade: t(c.cidade, 40) };
    const k = normaliza(o.nome) + '|' + o.tel.replace(/\D/g, '');
    if (vistosC.has(k)) continue;
    vistosC.add(k); clientes.push(o);
  }
  const vistosO = new Set(), orcamentos = [];
  for (const q of b.orcamentos.slice(0, 50000)) {
    if (!q || !t(q.cliente, 60)) continue;
    const dt = /^\d{4}-\d{2}-\d{2}$/.test(String(q.data || '')) ? String(q.data) : '';
    const o = { id: t(q.id, 30), orcNum: t(q.orcNum, 30), prazo: n(q.prazo), cliente: t(q.cliente, 60), projeto: t(q.projeto, 70), material: t(q.material, 50), m2: n(q.m2), valor: n(q.valor), entrada: n(q.entrada), status: t(q.status, 15), data: dt, arquivado: q.arquivado ? 1 : 0 };
    const k = o.id ? 'id:' + o.id : [normaliza(o.cliente), o.data, o.valor, normaliza(o.projeto)].join('|');
    if (vistosO.has(k)) continue;
    vistosO.add(k); orcamentos.push(o);
  }
  return { clientes, orcamentos };
}
const casaNome = (q, nome) => { const t = new Set(tokensPedra(nome || '')); return q.length > 0 && q.every(w => t.has(w)); };
// Etapa 63b: busca por nome de cliente no histórico completo salvo em KV (HIST_KEY). Só consulta; não grava nada.
// Retorna { ok, total, clientes, orcamentos } (mais recentes primeiro) ou { ok:false, motivo }.
async function buscarOrcamentosPorCliente(env, nome) {
  const q = tokensPedra(nome || '');
  if (!q.length) return { ok: false, motivo: 'nome_vazio' };
  const h = await lerHistorico(env);
  if (!h) return { ok: false, motivo: 'sem_historico' };
  const clientes = h.clientes.filter(c => casaNome(q, c.nome));
  const orcamentos = h.orcamentos.filter(o => casaNome(q, o.cliente)).sort((a, b) => String(b.data || '').localeCompare(String(a.data || '')));
  return { ok: true, total: orcamentos.length, clientes, orcamentos };
}
// Etapa 63c: ferramenta da IA do dono. Chama buscarOrcamentosPorCliente e devolve o resultado em texto para a IA.
async function consultarHistoricoCliente(env, a) {
  const nome = String((a && a.nome) || '').trim();
  const r = await buscarOrcamentosPorCliente(env, nome);
  if (!r.ok) {
    if (r.motivo === 'sem_historico') return { texto: 'O aplicativo ainda não enviou o histórico completo ao bot (abrir o aplicativo e aguardar cerca de 30 segundos resolve). Avise o Sr. Hangel e não invente dados.' };
    return { erro: true, texto: 'Informe o nome do cliente.' };
  }
  if (!r.clientes.length && !r.orcamentos.length) return { texto: `Nenhum cliente ou orçamento encontrado para "${nome}" no histórico completo (inclusive arquivados). Diga isso ao Sr. Hangel.` };
  const nomes = [...new Set([...r.clientes.map(c => c.nome), ...r.orcamentos.map(o => o.cliente)].map(x => normaliza(x)))];
  if (nomes.length > 1) {
    const rotulo = {}; for (const x of [...r.clientes.map(c => c.nome), ...r.orcamentos.map(o => o.cliente)]) rotulo[normaliza(x)] = rotulo[normaliza(x)] || x;
    const lista = nomes.slice(0, 10).map(k => `- ${rotulo[k]} (${r.orcamentos.filter(o => normaliza(o.cliente) === k).length} orçamento(s))`);
    return { texto: `Há ${nomes.length} nomes parecidos com "${nome}":\n${lista.join('\n')}${nomes.length > 10 ? '\n…' : ''}\nPergunte ao Sr. Hangel qual deles, ou consulte de novo com o nome completo.` };
  }
  const linhas = r.clientes.slice(0, 3).map(c => `CLIENTE: ${c.nome}${c.cidade ? ' — ' + c.cidade : ''}${c.tel ? ' — ' + c.tel : ''}`);
  const soma = r.orcamentos.reduce((t, o) => t + (Number(o.valor) || 0), 0);
  linhas.push(`${r.total} orçamento(s) no histórico completo (inclusive arquivados), do mais recente ao mais antigo; soma dos valores: R$ ${reais(soma)}.`);
  for (const o of r.orcamentos.slice(0, 25)) {
    linhas.push(`- ${o.data ? dataBR(o.data) : 's/ data'}${o.orcNum ? ' | ' + o.orcNum : ''} | ${o.projeto || 'serviço'}${o.material ? ' (' + o.material + ')' : ''} | à vista R$ ${reais(Number(o.valor) || 0)}${Number(o.prazo) > 0 ? ' | a prazo R$ ' + reais(Number(o.prazo)) : ''}${o.entrada ? ' | entrada R$ ' + reais(Number(o.entrada)) : ''} | ${o.status || '?'}${o.arquivado ? ' | arquivado' : ''}`);
  }
  if (r.total > 25) linhas.push(`… e mais ${r.total - 25} orçamento(s) mais antigos não listados.`);
  return { texto: linhas.join('\n').slice(0, 6000) };
}
async function tratarHistorico(env, from, msg) {
  const m = msg.match(/^(?:historico|buscar|procurar|consultar|ficha|orcamentos?|cliente)\s+(?:d[oae]s?\s+)?(.{2,40})$/);
  if (!m) return false;
  const q = tokensPedra(m[1]);
  if (!q.length) return false;
  const h = await lerHistorico(env);
  if (!h) { await enviar(env, from, 'Sr. Hangel, o aplicativo ainda não enviou o histórico completo ao bot. Abra o aplicativo, espere uns 30 segundos e tente de novo.'); return true; }
  const cli = h.clientes.filter(c => casaNome(q, c.nome));
  const orcs = h.orcamentos.filter(o => casaNome(q, o.cliente));
  if (!cli.length && !orcs.length) { await enviar(env, from, `Sr. Hangel, não encontrei "${m[1]}" entre os ${h.clientes.length} clientes e ${h.orcamentos.length} orçamentos do aplicativo (inclusive arquivados).`); return true; }
  const nomes = [...new Set([...cli.map(c => c.nome), ...orcs.map(o => o.cliente)].map(x => normaliza(x)))];
  const linhas = [];
  if (nomes.length > 1) {
    const rotulo = {}; for (const x of [...cli.map(c => c.nome), ...orcs.map(o => o.cliente)]) rotulo[normaliza(x)] = rotulo[normaliza(x)] || x;
    const lista = nomes.slice(0, 10).map(k => `• ${rotulo[k]} (${orcs.filter(o => normaliza(o.cliente) === k).length} orç.)`);
    await enviar(env, from, `Sr. Hangel, achei ${nomes.length} nomes parecidos com "${m[1]}":\n${lista.join('\n')}${nomes.length > 10 ? '\n…' : ''}\n\nEscreva o nome completo de um deles.`);
    return true;
  }
  for (const c of cli.slice(0, 3)) linhas.push(`*${c.nome}*${c.cidade ? ' — ' + c.cidade : ''}${c.tel ? ' — ' + c.tel : ''}`);
  if (orcs.length) {
    linhas.push('', `*${orcs.length} orçamento(s):*`);
    for (const o of orcs.slice(0, 8)) {
      linhas.push(`• ${o.data ? dataBR(o.data) : 's/ data'} — ${o.projeto || 'serviço'}${o.material ? ' (' + o.material + ')' : ''} — R$ ${reais(Number(o.valor) || 0)} — ${o.status || '?'}${o.arquivado ? ' [arquivado]' : ''}`);
    }
    if (orcs.length > 8) linhas.push(`… e mais ${orcs.length - 8} mais antigos.`);
  } else linhas.push('', 'Cliente cadastrado, sem orçamento.');
  await enviar(env, from, linhas.join('\n').slice(0, 3500));
  return true;
}
// v63: AGENDA DE CLIENTES UNIFICADA (bot + aplicativo)
//   ct:<número> (2 anos) — todo cliente que fala com o bot: nome confirmado, nome do perfil, último contato, interesse.
//   O nome fica no metadata da chave: listar a agenda inteira não lê chave por chave.
//   contatosTodos() junta: agenda do bot + clientes do app (snapshot e histórico, com telefone) → buscarClientes(nome|número).
//   GET /bot/contatos devolve a agenda do bot para o app completar o banco de clientes (nome ↔ telefone).
const CT_TTL = 2 * 365 * 86400;
async function ctAtualizar(env, num, info) {
  try {
    num = normalizarBR(num); if (!num || ehDono(env, num)) return;
    const k = 'ct:' + num;
    const { value, metadata } = await env.HR_KV.getWithMetadata(k);
    let o = null; try { o = JSON.parse(value || 'null'); } catch (_) {}
    o = o || { criado: Date.now() };
    const novo = { ...o };
    if (info.nome && nomeDoPerfil(info.nome, false)) novo.nome = String(info.nome).slice(0, 60);
    if (info.perfil) novo.perfil = String(info.perfil).slice(0, 60);
    if (info.interesse) novo.interesse = String(info.interesse).slice(0, 40);
    const agora = Date.now();
    const mudou = novo.nome !== o.nome || novo.perfil !== o.perfil || novo.interesse !== o.interesse || !o.ultimo || agora - o.ultimo > 12 * 3600000;
    if (!mudou) return;
    novo.ultimo = agora;
    await env.HR_KV.put(k, JSON.stringify(novo), { expirationTtl: CT_TTL, metadata: { n: (novo.nome || '').slice(0, 40), p: (novo.perfil || '').slice(0, 40), u: novo.ultimo } });
  } catch (e) { console.log('[CT]', e.message); }
}
async function ctListar(env) {
  const out = []; let cursor;
  for (let i = 0; i < 20; i++) {
    const r = await env.HR_KV.list({ prefix: 'ct:', cursor, limit: 1000 }).catch(() => null);
    if (!r) break;
    for (const k of r.keys) out.push({ numero: k.name.slice(3), nome: (k.metadata && k.metadata.n) || '', perfil: (k.metadata && k.metadata.p) || '', ultimo: (k.metadata && k.metadata.u) || 0 });
    if (r.list_complete || !r.cursor) break; cursor = r.cursor;
  }
  return out;
}
// 1ª vez: copia para a agenda os nomes que o bot já tinha guardado (nm:) e as conversas recentes
async function ctSemear(env) {
  if (await env.HR_KV.get('ct:semeado')) return 0;
  let n = 0;
  for (const pre of ['nm:', 'tx:']) {
    const r = await env.HR_KV.list({ prefix: pre, limit: 1000 }).catch(() => ({ keys: [] }));
    for (const k of r.keys) {
      const num = k.name.slice(pre.length); if (!/^\d{10,13}$/.test(num)) continue;
      let o = null; try { o = JSON.parse((await env.HR_KV.get(k.name)) || 'null'); } catch (_) {}
      const nome = pre === 'nm:' ? (o && o.nome) : (o && o.nome ? String(o.nome).split(' / ')[0] : '');
      if (nome) { await ctAtualizar(env, num, { nome }); n++; }
    }
  }
  await env.HR_KV.put('ct:semeado', '1');
  return n;
}
function telDoApp(t) { const d = String(t || '').replace(/\D/g, ''); if (d.length < 10) return ''; return normalizarBR(d.startsWith('55') && d.length >= 12 ? d : '55' + d); }
async function contatosTodos(env) {
  const mapa = new Map(), semTel = [];
  const add = (numero, nome, fonte, extra = {}) => {
    if (!nome && !numero) return;
    if (!numero) { semTel.push({ nome, numero: '', fontes: [fonte], ...extra }); return; }
    const k = ultimos8(numero), a = mapa.get(k);
    if (a) { if (!a.fontes.includes(fonte)) a.fontes.push(fonte); if (fonte === 'app' && nome) a.nome = nome; else if (!a.nome && nome) a.nome = nome; Object.assign(a, { ...extra, ...a, perfil: a.perfil || extra.perfil, ultimo: Math.max(a.ultimo || 0, extra.ultimo || 0) }); }
    else mapa.set(k, { numero, nome, fontes: [fonte], ...extra });
  };
  const [snap, hist, ct] = await Promise.all([lerSnapshotCompleto(env).catch(() => null), lerHistorico(env).catch(() => null), ctListar(env).catch(() => [])]);
  const app = [...((snap && snap.dados && snap.dados.clientes) || []), ...((hist && hist.clientes) || [])];
  for (const c of app) add(telDoApp(c.tel), String(c.nome || '').trim(), 'app', { cidade: c.cidade || '' });
  for (const c of ct) add(c.numero, c.nome, 'whatsapp', { perfil: c.perfil, ultimo: c.ultimo });
  for (const c of semTel) { // cliente do app sem telefone + mesma pessoa conversando no bot (mesmo nome ou nome do perfil) → junta
    const k = normaliza(c.nome); if (!k) continue;
    const par = [...mapa.values()].find(x => normaliza(x.nome) === k || normaliza(x.perfil || '') === k);
    if (par) { par.nome = c.nome; if (!par.fontes.includes('app')) par.fontes.push('app'); if (c.cidade && !par.cidade) par.cidade = c.cidade; c.juntado = true; }
  }
  const vistos = new Set([...mapa.values()].map(c => normaliza(c.nome)));
  return [...mapa.values(), ...semTel.filter(c => !c.juntado).filter(c => { const k = normaliza(c.nome); if (!k || vistos.has(k)) return false; vistos.add(k); return true; })];
}
// busca por nome (todas as palavras, aceitando plural/abreviação) ou por número; mais recentes e com telefone primeiro
async function buscarClientes(env, termo, max = 8) {
  const t = String(termo || '').trim(); if (!t) return [];
  const todos = await contatosTodos(env);
  const dig = t.replace(/\D/g, '');
  if (dig.length >= 8) return todos.filter(c => c.numero && ultimos8(c.numero) === dig.slice(-8)).slice(0, max);
  const q = tokensPedra(t); if (!q.length) return [];
  const casa = c => { const tk = new Set([...tokensPedra(c.nome || ''), ...tokensPedra(c.perfil || '')]); return q.every(w => tk.has(w) || [...tk].some(x => x.startsWith(w) && w.length >= 3)); };
  return todos.filter(casa).sort((a, b) => (!!b.numero - !!a.numero) || ((b.ultimo || 0) - (a.ultimo || 0))).slice(0, max);
}
async function telefoneDoClienteApp(env, nome) {
  const q = tokensPedra(nome);
  if (!q.length) return '';
  const snap = await lerSnapshotCompleto(env);
  const lista = snap && snap.dados && Array.isArray(snap.dados.clientes) ? snap.dados.clientes : [];
  const achados = lista.filter(c => { if (!c || !c.tel) return false; const t = new Set(tokensPedra(c.nome || '')); return q.every(w => t.has(w)); });
  const tels = [...new Set(achados.map(c => String(c.tel).replace(/\D/g, '')))].filter(d => d.length >= 10);
  if (tels.length !== 1) return '';
  const d = tels[0];
  return normalizarBR(d.startsWith('55') && d.length >= 12 ? d : '55' + d);
}
async function numeroDoClientePorNome(env, nome) {
  const ach = (await buscarClientes(env, nome).catch(() => [])).filter(c => c.numero); // v63: agenda unificada
  if (ach.length === 1 || (ach.length > 1 && new Set(ach.map(c => ultimos8(c.numero))).size === 1)) return ach[0].numero;
  const viaApp = await telefoneDoClienteApp(env, nome).catch(() => '');
  if (viaApp) return viaApp;
  const viaLivro = await livTelefone(env, nome); // telefone gravado no livro de entregas e pagamentos
  if (viaLivro) return normalizarBR(viaLivro);
  const q = tokensPedra(nome);
  if (!q.length) return '';
  const dono = ultimos8(numeroDono(env));
  const lista = await env.HR_KV.list({ prefix: 'ped:' });
  let melhor = null;
  for (const k of lista.keys) {
    let ped = null;
    try { ped = JSON.parse((await env.HR_KV.get(k.name)) || 'null'); } catch (_) {}
    if (!ped || ped.origem === 'dono' || !ped.numero || ultimos8(ped.numero) === dono) continue;
    const t = new Set(tokensPedra(ped.nome || ''));
    if (q.every(w => t.has(w)) && (!melhor || (ped.id || 0) > (melhor.id || 0))) melhor = ped;
  }
  return melhor ? melhor.numero : '';
}
// Boleto a receber? Usa o campo tipo do app; sem ele (cópias antigas), cai para a categoria
const bolEhReceber = b => (b.tipo ? b.tipo === 'receber' : ['parcela', 'saldo', 'cobranca', 'entrada'].includes(normaliza(String(b.categoria || ''))));
const nomeDoBoleto = b => String(b.cliente || b.cli || b.nome || b.pessoa || b.fornecedor || '').trim();
const dataBoleto = v => (/^\d{4}-\d{2}-\d{2}/.test(String(v || '')) ? dataBR(String(v).slice(0, 10)) : String(v || ''));
async function tratarCobranca(env, from, msg) {
  const m = msg.match(/^(?:cobrar|cobranca|cobrancas|lembrar boletos?|lembrete de boletos?)(?:\s+(?:d[oae]s?\s+)?(.{2,40}))?$/);
  if (!m) return false;
  const snap = await lerSnapshotCompleto(env);
  const d = (snap && snap.dados) || {};
  const todos = Array.isArray(d.boletos) ? d.boletos : [];
  if (!todos.length) { await enviar(env, from, 'Sr. Hangel, o aplicativo ainda não enviou os boletos ao bot. Abra o aplicativo para sincronizar e tente de novo.'); return true; }
  const hoje = dataBahia();
  const aReceber = b => (b.tipo ? b.tipo === 'receber' : ['parcela', 'saldo', 'cobranca', 'entrada'].includes(normaliza(String(b.categoria || ''))));
  let lista = todos.filter(b => b && (b.status === 'vencido' || (b.status === 'pendente' && b.vencimento && String(b.vencimento).slice(0, 10) < hoje)) && aReceber(b));
  if (lista.length && !lista.some(nomeDoBoleto)) {
    await enviar(env, from, 'Sr. Hangel, há boletos vencidos, mas os dados que o aplicativo envia ao bot não trazem o nome do cliente neles. Por isso não consigo saber a quem lembrar.');
    return true;
  }
  lista = lista.filter(nomeDoBoleto);
  if (m[1]) { const q = tokensPedra(m[1]); lista = lista.filter(b => { const t = new Set(tokensPedra(nomeDoBoleto(b))); return q.every(w => t.has(w)); }); }
  if (!lista.length) { await enviar(env, from, `Sr. Hangel, não há boleto de cliente vencido${m[1] ? ` para "${m[1]}"` : ''}.`); return true; }
  lista.sort((a, b) => String(a.vencimento).localeCompare(String(b.vencimento)));
  const semNumero = [];
  let mostrados = 0;
  for (const b of lista.slice(0, 3)) {
    const nome = nomeDoBoleto(b);
    const numero = await numeroDoClientePorNome(env, nome);
    if (!numero) { semNumero.push(nome); continue; }
    const key = Date.now().toString(36) + Math.random().toString(36).slice(2, 5);
    await env.HR_KV.put('cobr:' + key, JSON.stringify({ numero, nome, valor: Number(b.valor) || 0, venc: String(b.vencimento || '').slice(0, 10), desc: String(b.descricao || b.desc || '').slice(0, 80) }), { expirationTtl: 86400 });
    await enviarComBotoes(env, from, `Sr. Hangel, boleto vencido de *${nome}*:\n${b.valor ? 'R$ ' + reais(Number(b.valor) || 0) : 'valor não informado'}, vencimento em ${dataBoleto(b.vencimento)}.\n\nEnviar um lembrete educado a ele(a)?`,
      [{ id: 'cobr_ok|' + key, titulo: 'Enviar lembrete' }, { id: 'cobr_no', titulo: 'Não enviar' }]);
    mostrados++;
  }
  if (semNumero.length) await enviar(env, from, `Sr. Hangel, não tenho o número do WhatsApp de: ${[...new Set(semNumero)].join(', ')}. Esses o senhor precisa avisar pessoalmente.`);
  if (lista.length > 3) await enviar(env, from, `Mostrei os 3 boletos mais antigos de ${lista.length}. Depois de decidir, escreva *cobrar* de novo para ver os próximos.`);
  return true;
}
async function enviarLembreteBoleto(env, from, key) {
  let c = null;
  try { c = JSON.parse((await env.HR_KV.get('cobr:' + key)) || 'null'); } catch (_) {}
  if (!c) { await enviar(env, from, 'Sr. Hangel, essa solicitação expirou. Escreva *cobrar* para ver os boletos de novo.'); return; }
  if (await env.HR_KV.get('cobr:ult:' + c.numero)) { await enviar(env, from, `Sr. Hangel, já enviei um lembrete a ${c.nome} há menos de 3 dias. Para não incomodar, não enviei outro.`); return; }
  const p = nomeDeTratamento(c.nome) || 'Olá';
  const empresa = env.EMPRESA || 'HR Mármores e Granitos';
  const valor = c.valor ? `R$ ${reais(c.valor)}` : 'em aberto';
  const texto = `${p}, aqui é a assistente virtual da ${empresa}. Lembramos que o boleto${c.valor ? ' de ' + valor : ''}, com vencimento em ${dataBoleto(c.venc)}, consta em aberto. Se já efetuou o pagamento, desconsidere esta mensagem. Se precisar de ajuda ou de uma nova via, responda por aqui.`;
  let r = null;
  try { r = await enviarProativo(env, c.numero, texto, { nome: env.TEMPLATE_COBRANCA, params: [p, valor, dataBoleto(c.venc)] }); }
  catch (e) { console.log('[BOT] lembrete de boleto:', e.message); }
  if (!r) { await enviar(env, from, `Sr. Hangel, não consegui enviar a ${c.nome}: a conversa passou de 24 horas e não há modelo de aviso configurado. Escreva o senhor mesmo:\nwa.me/${c.numero}`); return; }
  if (r === 'texto' && env.PIX_CHAVE) await enviar(env, c.numero, `Se preferir pagar por Pix, a chave é: ${env.PIX_CHAVE}\nFavorecido: ${empresa}`).catch(e => falhou(env, 'enviarLembreteBoleto: enviar', e));
  await env.HR_KV.put('cobr:ult:' + c.numero, '1', { expirationTtl: 3 * 86400 });
  await env.HR_KV.delete('cobr:' + key);
  await enviar(env, from, `Pronto, Sr. Hangel. Enviei o lembrete a ${c.nome}.`);
}

// v33: o bot escreveu primeiro ao cliente (rascunho do dono): a mensagem entra no histórico da conversa,
// para a IA entender a resposta dele ("pode", "quero ver") no contexto do que foi enviado.
async function semearConversaProativa(env, numero, texto) {
  for (const n of variantesNumero(numero)) {
    const k = 'ca:' + n;
    let c = null; try { c = JSON.parse((await env.HR_KV.get(k)) || 'null'); } catch (_) {}
    if (!c || c.concluido) c = { dados: c && c.dados && c.dados.nome ? { nome: c.dados.nome } : {}, hist: (c && c.hist || []).slice(-4) };
    c.hist = [...(c.hist || []), { role: 'user', content: '[sem mensagem: a empresa escreveu primeiro a este cliente]' }, { role: 'assistant', content: String(texto).slice(0, 600) }].slice(-12);
    while (c.hist.length && c.hist[0].role !== 'user') c.hist.shift(); // a IA exige começar pelo cliente
    c.assuntoInicial = c.assuntoInicial || ('A empresa escreveu primeiro ao cliente: ' + String(texto).slice(0, 180));
    c.ultimaEm = Date.now();
    await env.HR_KV.put(k, JSON.stringify(c), { expirationTtl: CLIENTE_TTL });
  }
}
// rascunho de resposta ao cliente (ferramenta responder_cliente): envia ou cancela
async function decidirRascunho(env, from, enviarAgora) {
  let r = null; try { r = JSON.parse((await env.HR_KV.get('rascunho:resp')) || 'null'); } catch (_) {}
  if (!r) { await enviar(env, from, 'Não há nenhum rascunho aguardando, Sr. Hangel.'); return; }
  if (!enviarAgora) { await env.HR_KV.delete('rascunho:resp'); await enviar(env, from, 'Cancelado. Nada foi enviado.'); return; }
  // v20: só diz "Enviado" quando saiu de verdade. Dentro das 24 h manda texto livre; fora, usa o modelo TEMPLATE_RESPOSTA
  // (1 variável = o texto, até 200 caracteres). Sem modelo ou com texto maior, o rascunho é mantido e o dono recebe o link.
  const usaModelo = env.TEMPLATE_RESPOSTA && String(r.texto).length <= 200;
  let via = null, erro = '';
  try { via = await enviarProativo(env, r.numero, r.texto, usaModelo ? { nome: env.TEMPLATE_RESPOSTA, params: [r.texto] } : null); }
  catch (e) { erro = String(e.message || e).slice(0, 160); console.log('[BOT] responder_cliente:', erro); }
  if (!via) {
    await enviar(env, from, `Sr. Hangel, NÃO enviei. ${erro ? 'A Meta recusou: ' + erro + '.' : 'O cliente está fora da janela de 24 horas' + (env.TEMPLATE_RESPOSTA ? ' e o texto passa de 200 caracteres para o modelo.' : ' e não há modelo configurado (TEMPLATE_RESPOSTA).')}\n\nO rascunho continua guardado por 1 hora. Se preferir, escreva o senhor mesmo:\nwa.me/${r.numero}`);
    return;
  }
  await env.HR_KV.delete('rascunho:resp');
  await semearConversaProativa(env, r.numero, via === 'modelo' ? `Olá! Aqui é a assistente virtual da ${env.EMPRESA || 'HR Mármores e Granitos'}. ${r.texto}` : r.texto).catch(e => console.log('[BOT] semear conversa:', e.message));
  await enviar(env, from, via === 'modelo'
    ? 'Enviei ao cliente por modelo, Sr. Hangel (ele estava fora da janela de 24 h). Quando ele responder, o bot segue a conversa.'
    : 'Enviado ao cliente, Sr. Hangel.');
}
async function tratarAssumir(env, from, bruto, msg) {
  if (msg.split(' ').length <= 4 && !msg.includes('?')) {
    const sim = /^(isso|sim|pode|pode enviar|pode mandar|envia|enviar|manda|mandar|ok|confirmo|isso mesmo|positivo)$/.test(msg);
    const nao = /^(nao|cancela|cancelar|deixa|nao envia|nao mande|nao manda)$/.test(msg);
    if ((sim || nao) && await env.HR_KV.get('rascunho:resp')) { await decidirRascunho(env, from, sim); return true; }
  }
  const cmd = msg.match(/^(assumir|devolver)\b\s*(?:a\s+)?(?:conversa|cliente|atendimento)?\s*(.*)$/);
  if (cmd && msg.split(' ').length <= 8) {
    const assumir = cmd[1] === 'assumir';
    let num = numeroCliente(cmd[2]);
    if (!num && !assumir) { const l = await clientesAssumidos(env); if (l.length === 1) num = l[0]; }
    if (!num) num = await ultimoCliente(env);
    if (!num) { await enviar(env, from, 'Não encontrei nenhum cliente recente, Sr. Hangel. Escreva o comando com o número, por exemplo: *' + cmd[1] + ' 77 99999-8888*.'); return true; }
    const nome = await nomeParaDono(env, num);
    const quem = `${nome ? nome + ' (' : ''}wa.me/${num}${nome ? ')' : ''}`;
    if (assumir) {
      await env.HR_KV.put('humano:' + num, JSON.stringify({ nome, desde: Date.now() }), { expirationTtl: HUMANO_TTL });
      await enviar(env, from, `Pronto, Sr. Hangel. Assumi a conversa com ${quem}. O bot não responde mais a esse cliente e eu repasso aqui o que ele escrever.\n\nPara responder por aqui, escreva *responder* e o texto. Para religar o bot, escreva *devolver*. Se esquecer, o bot volta sozinho em 12 horas.`);
    } else {
      await env.HR_KV.delete('humano:' + num);
      await enviar(env, from, `Devolvido, Sr. Hangel. O bot voltou a atender ${quem}.`);
    }
    return true;
  }
  if (await tratarPrazosComando(env, from, msg)) return true;
  if (await tratarEntregue(env, from, msg)) return true;
  if (await tratarHorariosVisitaDono(env, from, bruto, msg)) return true; // resposta do dono com os horários livres para a visita de um cliente
  if (await tratarLivroComando(env, from, msg)) return true; // "entregas" / "entregas <cliente>": livro de entregas e pagamentos
  if (await tratarPronto(env, from, msg)) return true;
  if (await tratarConciliacao(env, from, msg)) return true;
  if (await tratarDiagnosticoWebhook(env, from, msg)) return true; // "diagnóstico webhook"
  if (await tratarRecebiDinheiro(env, from, bruto, msg)) return true; // "recebi 72,13 do fulano em dinheiro": baixa na cobrança + finanças
  if (await tratarExtratoMP(env, from, msg)) return true;
  if (await tratarReceberComando(env, from, msg, bruto)) return true; // Etapa 72: "a receber", "telefone <cliente> <número>", "parar aviso <cliente>"
  if (await tratarCobrancaD1Comando(env, from, msg)) return true; // "cobrar pix" (módulo novo); o "cobrar" antigo segue abaixo
  if (await tratarHistorico(env, from, msg)) return true; // Etapa 63: "historico <nome>"
  if (await tratarCobranca(env, from, msg)) return true;
  if (await tratarEtapa28Comandos(env, from, bruto, msg)) return true;
  if (/^guardar( resposta)?$/.test(msg)) {
    let u = null;
    try { u = JSON.parse((await env.HR_KV.get('pq:ult')) || 'null'); } catch (_) {}
    if (!u) return false; // nada para guardar: segue o fluxo normal do dono
    const texto = `Se perguntarem "${u.pergunta}", responda: ${u.resposta}`.replace(/\s+/g, ' ').slice(0, 300);
    const mem = await lerMemoria(env);
    if (mem.length >= MEM_MAX) { await enviar(env, from, 'A memória do bot está cheia, Sr. Hangel. Peça para esquecer algo antes de guardar.'); return true; }
    if (!mem.some(m => normaliza(m.texto) === normaliza(texto))) {
      const id = Date.now().toString(36).slice(-4) + Math.random().toString(36).slice(2, 4);
      mem.push({ id, texto, escopo: 'atendimento', ts: Date.now() });
      await salvarMemoria(env, mem);
      await removerFrequencia(env, u.pergunta);
      await enviarComBotoes(env, from, `Guardado, Sr. Hangel. O bot passará a responder assim:\n\n_${texto}_`, [{ id: 'mem_esq|' + id, titulo: 'Esquecer' }]);
    } else await enviar(env, from, 'Essa resposta já estava guardada.');
    await env.HR_KV.delete('pq:ult');
    return true;
  }
  const r = bruto.match(/^\s*responder\s+(?:(\+?[\d\s()-]{10,}?)\s*[:,]?\s+)?([\s\S]+)$/i);
  if (r) {
    const lista = await clientesAssumidos(env);
    const pend = await lerPerguntasPendentes(env);
    const citado = env._ctx && env._ctx.citado ? (await env.HR_KV.get('wm:' + env._ctx.citado).catch(() => null)) || '' : ''; // aviso deslizado → cliente
    if (!citado && !lista.length && !pend.length) return false; // nada esperando resposta: segue o fluxo normal do dono
    let num = numeroCliente(r[1]) || citado;
    if (!num) {
      const u = await ultimoCliente(env);
      const cands = [...new Set([...lista, ...pend.map(x => x.numero)])];
      num = cands.length === 1 ? cands[0] : (cands.includes(u) ? u : '');
    }
    if (!num) {
      const cands = [...new Set([...lista, ...pend.map(x => x.numero)])].slice(0, 9);
      const linhas = [];
      for (const n of cands) linhas.push({ id: 'rsp|' + n, titulo: ((await nomeParaDono(env, n)) || 'Cliente ' + n.slice(-4)).slice(0, 24), descricao: 'final ' + n.slice(-4) });
      await env.HR_KV.put('rsp:txt', r[2].trim().slice(0, 1500), { expirationTtl: 15 * 60 });
      await enviarLista(env, from, 'Há mais de um cliente esperando, Sr. Hangel. Para quem vai essa resposta? Dica: deslize o aviso do cliente e escreva *responder* e o texto.', 'Escolher cliente', linhas, true);
      return true;
    }
    const pergunta = pend.filter(x => x.numero === num).pop();
    if (!citado && !lista.includes(num) && !pergunta) { await enviar(env, from, 'Esse cliente não está com a conversa assumida nem tem pergunta esperando. Escreva *assumir* primeiro.'); return true; }
    const texto = r[2].trim().slice(0, 1500);
    await enviar(env, num, texto);
    const outros = pergunta && pergunta.outros ? pergunta.outros : [];
    for (const o of outros) await enviar(env, o.numero, texto).catch(e => console.log('[BOT] resposta a outro cliente:', e.message));
    if (pergunta) {
      await env.HR_KV.put('pq:lista', JSON.stringify(pend.filter(x => x.em !== pergunta.em)), { expirationTtl: 7 * 86400 });
      await env.HR_KV.put('pq:ult', JSON.stringify({ pergunta: pergunta.pergunta, resposta: texto }), { expirationTtl: 2 * 60 * 60 });
      if (pergunta.aprender) await aprenderResposta(env, from, pergunta.pergunta, texto, outros.length);
      else await enviar(env, from, `Enviado para *${(await nomeParaDono(env, num)) || num}*. Se quiser que o bot responda igual nas próximas vezes, escreva *guardar*.`);
    } else await enviar(env, from, `Enviado para *${(await nomeParaDono(env, num)) || num}*.${!lista.includes(num) ? '\n_O bot continua atendendo esse cliente. Para ele parar de responder, escreva *assumir*._' : ''}`);
    return true;
  }
  return false;
}
// depois que o dono responde uma pergunta sem resposta, o bot pergunta se ele quer guardar a resposta como regra de atendimento
async function aprenderResposta(env, from, pergunta, resposta, qtdOutros = 0) {
  const texto = `Se perguntarem "${pergunta}", responda: ${resposta}`.replace(/\s+/g, ' ').slice(0, 300);
  await enviarComBotoes(env, from, `Enviado ao cliente${qtdOutros ? ` e a mais ${qtdOutros} que perguntaram o mesmo` : ''}, Sr. Hangel. Quer que o bot responda assim nas próximas vezes?\n\n_${texto}_`, [{ id: 'pq_guardar', titulo: 'Guardar' }, { id: 'pq_nao', titulo: 'Não guardar' }]);
}
// ── v74: o cliente pede para falar com uma pessoa ──
// Detecção restrita: só texto, mensagem curta e frases claras (\"pessoa\" solta dentro de outro assunto não dispara; negação também não).
function pedeAtendimentoHumano(bruto) {
  const t = normaliza(String(bruto || '')).replace(/[.,;:]+/g, ' ').replace(/\s+/g, ' ').trim();
  if (!t || t.length > 90 || t.split(' ').length > 14) return false;
  if (/\b(nao|nem|nunca|sem)\b.{0,30}\b(falar|conversar|atendente|humano|ligar|liga|ligue|dono|pessoa)\b/.test(t)) return false;
  const alvo = '(?:uma |um |o |a |com )?(?:pessoa|pessoas|alguem|atendente|humano|ser humano|dono|dona|responsavel|proprietario|gerente|equipe|alguem da equipe|pessoa da equipe|hangel|seu hangel|senhor hangel)';
  if (new RegExp('^(?:por favor |pf |pfv )?(?:o |um |uma )?(?:atendente|humano|dono|dona|responsavel|atendimento humano|pessoa de verdade|ser humano)(?: por favor| pf| pfv)?$').test(t)) return true;
  if (new RegExp('\\b(?:falar|conversar|trocar uma ideia|tratar)\\s+(?:direto\\s+)?(?:com|c)\\s+' + alvo + '\\b').test(t)) return true;
  if (new RegExp('\\b(?:quero|queria|preciso|gostaria|prefiro|posso|pode|podem|da pra|dá pra)\\b.{0,25}\\b(?:atendente|atendimento humano|pessoa de verdade|ser humano|falar com (?:uma )?pessoa)\\b').test(t)) return true;
  if (new RegExp('\\b(?:chama|chame|chamar|passa|passe|passar|transfere|transfira|transferir|encaminha|encaminhe)\\b.{0,20}\\b(?:dono|dona|responsavel|atendente|alguem|humano|pessoa|proprietario|hangel)\\b').test(t)) return true;
  if (/\b(?:me liga|me ligue|me ligar|pode me ligar|podem me ligar|pode ligar pra mim|pode ligar para mim|ligue pra mim|ligue para mim|liga pra mim|liga para mim|me telefona|me telefone|quero uma ligacao|prefiro ligacao|prefiro que ligue)\b/.test(t)) return true;
  return false;
}

async function tratarPedidoHumano(env, from, m) {
  if (!m || m.type !== 'text') return false;
  const bruto = String((m.text && m.text.body) || '');
  if (!pedeAtendimentoHumano(bruto)) return false;
  const nome = await nomeParaDono(env, from).catch(() => '');
  await env.HR_KV.put('humano:' + from, JSON.stringify({ nome, desde: Date.now(), origem: 'cliente' }), { expirationTtl: HUMANO_TTL });
  const u = ultimos8(from);
  if (u) await env.HR_KV.put('apr2:' + u, '1', { expirationTtl: apresTtl(env) }).catch(() => {}); // quem pede uma pessoa não recebe o banner de apresentação
  try { await enviar(env, from, `Claro, vou chamar o responsável agora. Ele responde por aqui em breve. Se preferir falar direto, o número é ${fmtTel(contatoHumano(env))} (wa.me/${contatoHumano(env)}).`); }
  catch (e) { console.log('[BOT] resposta ao pedido de atendente:', e.message); }
  await notificarDono(env, Date.now(), `*${nome || 'Cliente'}* pediu para falar com uma pessoa: \"${bruto.replace(/\s+/g, ' ').slice(0, 200)}\"\n\nO bot parou de responder a ele e repassa aqui o que ele escrever. Para religar o bot, escreva *devolver*.\nwa.me/${from}`).catch(e => console.log('[BOT] aviso de pedido de atendente:', e.message));
  return true;
}

// mensagem de cliente com a conversa assumida: o bot não responde, só repassa ao dono
async function repassarAoDono(env, from, m) {
  let texto = '';
  if (['image', 'video', 'document'].includes(m.type)) texto = (await receberMidiaCliente(env, from, m)) || '[arquivo]';
  else if (m.type === 'audio') texto = '[áudio]';
  else texto = extrairTexto(m) || '';
  const nome = await nomeParaDono(env, from);
  await notificarDono(env, Date.now(), `*${nome || 'Cliente'}* escreveu: "${String(texto).slice(0, 500)}"\n\nPara responder, deslize e escreva *responder* e o texto.\nwa.me/${from}`);
}

// ══════════════════════════════════════════════════════════════════════
// HR VISION · parte 1 — recebimento de imagens e PDFs (cliente e dono)
// Só RECEBE e PREPARA o arquivo. NÃO há OCR/leitura aqui (é a próxima etapa).
//   vision:r:<id>  registro (JSON): remetente, hora, tipo, mime, tamanho, sha256, status
//   vision:f:<id>  bytes do arquivo, prontos para a etapa de leitura
// <id> começa pela hora em 13 dígitos, então listar o prefixo "vision:r:" já devolve em ordem; a próxima
// etapa processa os registros com status RECEBIDO. Status possíveis: RECEBIDO | REJEITADO | ERRO.
// Variável opcional: VISION=0 desliga tudo (volta ao comportamento anterior).
// ══════════════════════════════════════════════════════════════════════
const VISION_ON = env => String(env.VISION ?? '1') !== '0';
const VISION_TTL_REG = 60 * 86400;
const VISION_TTL_ARQ = 14 * 86400;
const VISION_MAX_BYTES = { imagem: 10 * 1048576, pdf: 20 * 1048576 }; // o KV aceita até 25 MiB por valor
const VISION_MIMES = { imagem: ['image/jpeg', 'image/png', 'image/webp'], pdf: ['application/pdf'] };
const VISION_HOSTS = ['fbcdn.net', 'facebook.com', 'fbsbx.com', 'whatsapp.net', 'whatsapp.com']; // o download só vale se vier da Meta
const VISION_TIMEOUT_MS = 25000;
const VISION_CONFIRMACAO = '📡 HR VISION | DOCUMENTO RECEBIDO\n\nArquivo recebido com sucesso!\n\nNosso sistema está preparando o documento para análise.\n\nStatus: RECEBIDO.\n\nHR MÁRMORES E GRANITOS.';

class VisionErro extends Error { constructor(codigo, msg) { super(msg); this.codigo = codigo; } }

// 'imagem' | 'pdf' | null. Imagens do dono com legenda de perfil/portfólio/pedra seguem o fluxo antigo.
function visionTipo(env, m, dono) {
  if (!VISION_ON(env) || !m) return null;
  if (m.type === 'image' && m.image && m.image.id) {
    if (dono) {
      const leg = String(m.image.caption || '').trim();
      if (/^(portf[oó]lio|trabalho|pedra)\s*:?\s*(.*)$/i.test(leg) || LEGENDAS_FOTO.includes(normaliza(leg))) return null;
    }
    return 'imagem';
  }
  if (m.type === 'document' && m.document && m.document.id) {
    const mime = String(m.document.mime_type || '').split(';')[0].trim().toLowerCase();
    if (mime === 'application/pdf' || /\.pdf$/i.test(String(m.document.filename || ''))) return 'pdf';
  }
  return null;
}

function visionHora(m) {
  const s = Number(m && m.timestamp); // a Meta manda segundos desde 1970
  const ms = Number.isFinite(s) && s > 1e9 && s < 4e9 ? s * 1000 : Date.now();
  const d = new Date(ms);
  let bahia = '';
  try { bahia = new Intl.DateTimeFormat('pt-BR', { timeZone: 'America/Bahia', dateStyle: 'short', timeStyle: 'medium' }).format(d); } catch (_) {}
  return { ms, iso: d.toISOString(), bahia };
}

function visionAssinaturaOk(mime, buf) {
  const u = new Uint8Array(buf, 0, Math.min(buf.byteLength, 16));
  const eq = (...x) => x.every((v, i) => u[i] === v);
  if (mime === 'image/jpeg') return eq(0xFF, 0xD8, 0xFF);
  if (mime === 'image/png') return eq(0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A);
  if (mime === 'image/webp') return eq(0x52, 0x49, 0x46, 0x46) && u[8] === 0x57 && u[9] === 0x45 && u[10] === 0x42 && u[11] === 0x50;
  if (mime === 'application/pdf') { // o cabeçalho %PDF- pode estar em qualquer ponto dos primeiros 1024 bytes
    return new TextDecoder('latin1').decode(new Uint8Array(buf, 0, Math.min(buf.byteLength, 1024))).includes('%PDF-');
  }
  return false;
}

// Download seguro pela API oficial: id numérico, endereço da Meta, tipo permitido, tamanho limitado, tempo limitado,
// conferência do conteúdo (assinatura do arquivo) e do SHA-256 informado pela Meta.
async function visionBaixar(env, mediaId, tipo) {
  const id = String(mediaId || '');
  if (!/^\d{5,30}$/.test(id)) throw new VisionErro('id', 'identificador de mídia inválido');
  const max = VISION_MAX_BYTES[tipo];
  const ctl = new AbortController();
  const timer = setTimeout(() => ctl.abort(), VISION_TIMEOUT_MS);
  try {
    let meta;
    try { meta = await graphJson(env, `https://graph.facebook.com/${gv(env)}/${id}`, { headers: authBearer(env), signal: ctl.signal }); }
    catch (e) { throw new VisionErro(e && e.name === 'AbortError' ? 'tempo' : 'meta', 'consulta da mídia falhou: ' + (e && e.message)); }
    let u;
    try { u = new URL(meta && meta.url); } catch (_) { throw new VisionErro('url', 'a Meta não devolveu o endereço do arquivo'); }
    const host = u.hostname.toLowerCase();
    if (u.protocol !== 'https:' || u.username || u.password || !VISION_HOSTS.some(h => host === h || host.endsWith('.' + h))) {
      throw new VisionErro('url', 'endereço de download fora da Meta: ' + host);
    }
    const mime = String(meta.mime_type || '').split(';')[0].trim().toLowerCase();
    if (!VISION_MIMES[tipo].includes(mime)) throw new VisionErro('tipo', 'tipo de arquivo não aceito: ' + (mime || 'desconhecido'));
    if (Number(meta.file_size) > max) throw new VisionErro('grande', 'arquivo de ' + meta.file_size + ' bytes passa do limite');
    let buf;
    try {
      const r = await fetch(u.href, { headers: authBearer(env), signal: ctl.signal });
      if (!r.ok) throw new VisionErro('download', 'download recusado (' + r.status + ')');
      if (Number(r.headers.get('content-length')) > max) throw new VisionErro('grande', 'arquivo passa do limite');
      buf = await r.arrayBuffer();
    } catch (e) {
      if (e instanceof VisionErro) throw e;
      throw new VisionErro(e && e.name === 'AbortError' ? 'tempo' : 'download', 'download falhou: ' + (e && e.message));
    }
    if (!buf.byteLength) throw new VisionErro('vazio', 'arquivo vazio');
    if (buf.byteLength > max) throw new VisionErro('grande', 'arquivo passa do limite');
    if (!visionAssinaturaOk(mime, buf)) throw new VisionErro('assinatura', 'o conteúdo não corresponde ao tipo ' + mime);
    const dig = new Uint8Array(await crypto.subtle.digest('SHA-256', buf));
    const sha256 = [...dig].map(b => b.toString(16).padStart(2, '0')).join('');
    if (meta.sha256 && String(meta.sha256).toLowerCase() !== sha256) throw new VisionErro('integridade', 'SHA-256 diferente do informado pela Meta');
    return { buf, mime, sha256, size: buf.byteLength };
  } finally { clearTimeout(timer); }
}

// A confirmação leva o emoji do pedido: o filtro global semEmoji() (enviar/enviarTextoPuro) o removeria, então esta mensagem sai direto.
async function visionEnviarTexto(env, para, texto) {
  const r = await fetch(`https://graph.facebook.com/${gv(env)}/${env.PHONE_NUMBER_ID}/messages`, {
    method: 'POST', headers: { ...authBearer(env), 'Content-Type': 'application/json' },
    body: JSON.stringify({ messaging_product: 'whatsapp', to: normalizarBR(para), type: 'text', text: { body: texto, preview_url: false } }),
  });
  if (!r.ok) throw new Error(`WhatsApp API ${r.status}: ${(await r.text().catch(() => '')).slice(0, 200)}`);
}

function visionMsgErro(codigo) {
  const topo = 'HR VISION | NÃO FOI POSSÍVEL RECEBER\n\n';
  const fim = '\n\nStatus: NÃO RECEBIDO.\n\nHR MÁRMORES E GRANITOS.';
  if (codigo === 'grande') return topo + `Esse arquivo passa do tamanho permitido (imagem até ${VISION_MAX_BYTES.imagem / 1048576} MB, PDF até ${VISION_MAX_BYTES.pdf / 1048576} MB).\nPor favor, envie uma versão menor.` + fim;
  if (['tipo', 'assinatura', 'integridade', 'vazio', 'id', 'url'].includes(codigo)) return topo + 'Não consegui validar esse arquivo.\nEnvie uma foto (JPG ou PNG) ou um PDF.' + fim;
  return topo + 'Não consegui baixar o arquivo agora.\nPor favor, envie novamente em instantes.' + fim;
}

async function visionGravarRegistro(env, rec) {
  try { await env.HR_KV.put('vision:r:' + rec.id, JSON.stringify(rec), { expirationTtl: VISION_TTL_REG }); return true; }
  catch (e) { console.log('[VISION] não consegui gravar o registro:', e.message); return false; }
}

// Devolve true quando a mensagem deve seguir o fluxo normal (cliente que escreveu legenda; PDF do dono com legenda-comando).
async function tratarVision(env, from, m, dono, tipo) {
  try {
    const info = m[m.type] || {};
    const hora = visionHora(m);
    const legenda = String(info.caption || '').trim().slice(0, 300);
    const origem = ehDono(env, from) ? 'dono' : 'cliente';
    const nome = origem === 'dono' ? 'Proprietário' : ((await lerNomeSalvo(env, from).catch(() => '')) || nomeDoPerfil(m._perfil) || 'Cliente');
    const id = String(Date.now()).padStart(13, '0') + '-' + crypto.randomUUID().slice(0, 8);
    const rec = {
      id, versao: 1, tipo, origem, de: normalizarBR(from), nome, wamid: m.id || '', midia_id: String(info.id || ''),
      nome_arquivo: tipo === 'pdf' ? String(info.filename || 'documento.pdf').slice(0, 120) : '', legenda,
      mime: '', tamanho: 0, sha256: '', mensagem_em: hora.iso, mensagem_em_bahia: hora.bahia,
      registrado_em: new Date().toISOString(), status: 'RECEBIDO', arquivo_guardado: false, erro: null,
    };
    let midia = null;
    try {
      midia = await visionBaixar(env, info.id, tipo);
      rec.mime = midia.mime; rec.tamanho = midia.size; rec.sha256 = midia.sha256;
      await env.HR_KV.put('vision:f:' + id, midia.buf, { expirationTtl: VISION_TTL_ARQ });
      rec.arquivo_guardado = true;
    } catch (e) {
      const codigo = (e instanceof VisionErro && e.codigo) || 'armazenamento';
      rec.status = ['grande', 'tipo', 'assinatura', 'integridade', 'vazio', 'id', 'url'].includes(codigo) ? 'REJEITADO' : 'ERRO';
      rec.erro = { codigo, detalhe: String((e && e.message) || e).slice(0, 200) };
      console.log('[VISION] falha ao receber:', codigo, rec.erro.detalhe);
    }
    await visionGravarRegistro(env, rec);

    if (rec.status !== 'RECEBIDO') {
      await enviar(env, from, visionMsgErro(rec.erro.codigo)).catch(e => console.log('[VISION] aviso de falha:', e.message));
      if (!dono) {
        await notificarDono(env, Date.now(), `*HR VISION:* ${nome} enviou ${tipo === 'pdf' ? 'um PDF' : 'uma imagem'} e não consegui receber (${rec.erro.codigo}: ${rec.erro.detalhe.slice(0, 80)}).\nwa.me/${normalizarBR(from)}`).catch(() => {});
      }
      return false;
    }
    console.log(`[VISION] recebido ${id} ${tipo} ${rec.mime} ${rec.tamanho}B de ${origem} ...${ultimos8(from).slice(-4)}`);
    if (!dono) await receberMidiaCliente(env, from, m, { buf: midia.buf, tipo: midia.mime }); // a equipe continua recebendo a cópia, sem baixar de novo
    if (!dono) { // v33: cliente no funil de bancada mandou o projeto: lido ao pé da letra e a conversa segue (sem a confirmação genérica)
      const tp = await receberProjetoBancada(env, from, midia.buf, midia.mime).catch(e => { console.log('[BOT] projeto:', e.message); return ''; });
      if (tp) { m._projeto = tp; return true; }
    }
    try { await visionEnviarTexto(env, from, VISION_CONFIRMACAO); }
    catch (e) {
      console.log('[VISION] confirmação direta falhou:', e.message);
      await enviarTextoPuro(env, from, VISION_CONFIRMACAO).catch(e2 => console.log('[VISION] confirmação falhou:', e2.message));
    }
    return !!legenda && !(dono && tipo === 'imagem');
  } catch (e) {
    console.log('[VISION] erro inesperado:', e && e.message);
    return false;
  }
}

async function tratarMensagem(env0, m) {
  const ctx = { voz: false, falou: false, cliente: false, textos: [], suprimiu: false, de: normalizarBR(m.from), citado: (m.context && m.context.id) || '', paraDono: [], agente: false, bruto: '', tx: [] };
  const env = Object.create(env0);
  env._ctx = ctx;
  if (!ehDono(env0, m.from)) { // v62: transcrição
    const ent = extrairTexto(m) || (m.interactive && ((m.interactive.button_reply && m.interactive.button_reply.title) || (m.interactive.list_reply && m.interactive.list_reply.title))) || (m.button && m.button.text) || '';
    ctx.tx.push({ q: 'c', t: Date.now(), x: String(ent || ({ image: '[foto]', video: '[vídeo]', document: '[arquivo]', audio: '[áudio]', sticker: '[figurinha]', location: '[localização]', contacts: '[contato]' }[m.type] || '[' + (m.type || 'mensagem') + ']')).slice(0, 1200) });
  }
  await tratarMensagemBase(env, m, ctx);
  if (ctx.cliente) { await avisarInicioConversa(env, m).catch(e => console.log('[BOT] aviso de início:', e.message)); ctx.cliente = false; } // v53: antes do registro abaixo, para a IA do dono saber quem chamou
  if (ehDono(env0, m.from) && !ctx.agente && ctx.paraDono.length) await agNota(env, ctx.bruto || extrairTexto(m) || '[mensagem do Sr. Hangel]', ctx.paraDono.join('\n')); // v48: a IA sabe o que as rotinas responderam
  else if (!ehDono(env0, m.from) && ctx.paraDono.length) await agNota(env, null, '[Aviso do bot ao Sr. Hangel] ' + ctx.paraDono.join('\n')); // v48: avisos sobre clientes/funcionários
  if (ctx.cliente) await avisarInicioConversa(env, m).catch(e => console.log('[BOT] aviso de início:', e.message));
  if (ctx.voz && !ctx.falou && ctx.textos.length) {
    const fala = textoParaFala(ctx.textos.join('\n\n'));
    if (!ehDono(env0, m.from)) ctx.tx.push({ q: 'b', t: Date.now(), x: '[áudio] ' + ctx.textos.join(' ').slice(0, 1100) }); // v62
    // cliente que falou só recebe áudio; se o áudio não couber ou falhar, o texto sai para ele não ficar sem resposta
    const cabe = fala.length <= VOZ_MAX_CHARS;
    const ok = cabe && await enviarVoz(env, m.from, fala);
    if (!ok && ctx.suprimiu) await enviarTextoPuro(env, m.from, ctx.textos.join('\n\n')).catch(e => console.log('[BOT] texto de reserva:', e.message));
  }
  if (ctx.tx.length) { const nm = [await lerNomeSalvo(env0, m.from).catch(() => ''), nomeDoPerfil(m._perfil)].filter(Boolean).filter((v, i, a) => a.indexOf(v) === i).join(' / '); await txGravar(env0, m.from, ctx.tx.splice(0), nm); await ctAtualizar(env0, m.from, { nome: await lerNomeSalvo(env0, m.from).catch(() => ''), perfil: nomeDoPerfil(m._perfil) || '' }); } // v62 · v63
}

// ── HR COMMS · etapa 66 — preparação e envio aprovado de mensagens comuns ──
// Contatos e rascunhos ficam no KV. Nenhuma mensagem a terceiros sai sem aprovação explícita do dono.
function commsChaveNome(nome) {
  return normaliza(nome).replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '').slice(0, 48);
}
function commsNumeroValido(n) {
  const d = String(n || '').replace(/\D/g, '');
  return d.length >= 10 && d.length <= 15 ? d : '';
}
async function commsSalvarContato(env, nome, numero, extra = {}) {
  const chave = commsChaveNome(nome), n = commsNumeroValido(numero);
  if (!chave || !n) return false;
  const reg = { nome: String(nome).trim().slice(0, 80), numero: n, atualizado: Date.now(), origem: extra.origem || 'proprietario' };
  await env.HR_KV.put('comms:contato:' + chave, JSON.stringify(reg));
  return true;
}
async function commsBuscarContato(env, nome) {
  const chave = commsChaveNome(nome);
  if (!chave) return null;
  const raw = await env.HR_KV.get('comms:contato:' + chave);
  if (!raw) return null;
  try { const c = JSON.parse(raw); return commsNumeroValido(c.numero) ? c : null; } catch (_) { return null; }
}
function commsContatoCompartilhado(m) {
  const c = Array.isArray(m?.contacts) ? m.contacts[0] : null;
  if (!c) return null;
  const nome = c.name?.formatted_name || c.name?.first_name || '';
  const tel = c.phones?.find(x => x.wa_id)?.wa_id || c.phones?.[0]?.phone || c.phones?.[0]?.wa_id || '';
  return nome && commsNumeroValido(tel) ? { nome, numero: tel } : null;
}
async function commsTratarDono(env, from, bruto, m) {
  const t = String(bruto || '').trim();
  if (!t) return false;
  const norm = normaliza(t);
  // Guardar contato por comando explícito: contato: Nome, telefone
  let mc = t.match(/^contato\s*:\s*(.{2,80}?)\s*[,;|–-]\s*([+\d()\s.-]{10,22})$/i);
  if (mc) {
    if (await commsSalvarContato(env, mc[1], mc[2])) {
      await enviar(env, from, `Contato *${mc[1].trim()}* salvo. Agora posso preparar mensagens para essa pessoa.`);
    } else await enviar(env, from, 'Não consegui salvar. Confira o nome e o número com DDD e tente novamente.');
    return true;
  }
  // Se o dono compartilhou um cartão de contato, salva pelo nome do cartão.
  const compartilhado = commsContatoCompartilhado(m);
  if (compartilhado) {
    await commsSalvarContato(env, compartilhado.nome, compartilhado.numero, { origem: 'contato_compartilhado' });
    await enviar(env, from, `Contato *${compartilhado.nome}* salvo com o número recebido. Quando quiser, peça para preparar uma mensagem.`);
    return true;
  }
  // Aguardar aprovação explícita de um rascunho.
  const pendRaw = await env.HR_KV.get('comms:rascunho:' + ultimos8(from));
  if (pendRaw) {
    let pend = null; try { pend = JSON.parse(pendRaw); } catch (_) {}
    if (pend && norm === 'cancelar mensagem') {
      await env.HR_KV.delete('comms:rascunho:' + ultimos8(from));
      await enviar(env, from, 'Mensagem cancelada. Nada foi enviado.');
      return true;
    }
    if (pend && norm.startsWith('editar mensagem:')) {
      const novo = t.slice(t.indexOf(':') + 1).trim();
      if (!novo) { await enviar(env, from, 'Envie o texto depois de “editar mensagem:”.'); return true; }
      pend.texto = novo.slice(0, 4000); pend.atualizado = Date.now();
      await env.HR_KV.put('comms:rascunho:' + ultimos8(from), JSON.stringify(pend), { expirationTtl: 86400 });
      await enviar(env, from, `*PRÉVIA ATUALIZADA — HR COMMS*\n\nDestinatário: ${pend.nome} (${pend.numero})\n\n${pend.texto}\n\nResponda *APROVAR MENSAGEM* para enviar ou *CANCELAR MENSAGEM* para descartar.`);
      return true;
    }
    if (pend && ['aprovar mensagem', 'aprovar envio', 'enviar mensagem'].includes(norm)) {
      // WhatsApp permite texto livre apenas dentro da janela de atendimento de 24h do destinatário.
      const ultima = Math.max(Number(await env.HR_KV.get('ult:' + pend.numero)) || 0, Number(await env.HR_KV.get('ult:' + normalizarBR(pend.numero))) || 0);
      if (!ultima || Date.now() - ultima > 24 * 60 * 60 * 1000) {
        await enviar(env, from, `A mensagem foi aprovada, mas não pode ser enviada como texto livre porque ${pend.nome} está fora da janela de 24 horas do WhatsApp. É necessário um modelo (template) aprovado pela Meta. O rascunho foi mantido; nada foi enviado.`);
        return true;
      }
      try {
        await enviarTextoPuro(env, pend.numero, pend.texto);
        await env.HR_KV.delete('comms:rascunho:' + ultimos8(from));
        await enviar(env, from, `Mensagem enviada para *${pend.nome}* com sua aprovação.`);
      } catch (e) {
        await enviar(env, from, `Não consegui enviar a mensagem para ${pend.nome}. O rascunho foi mantido. Motivo: ${String(e.message || e).slice(0, 180)}`);
      }
      return true;
    }
  }
  // Associação sem número: não inventa telefone nem interpreta como cobrança.
  const assoc = t.match(/^(.{2,60}?)\s+(?:e|é)\s+(?:o|a)?\s*(?:contato|responsavel|responsável)\s+(?:da|do|de)\s+(.{2,60})$/i);
  if (assoc) {
    const achou = await commsBuscarContato(env, assoc[1]);
    if (achou) await enviar(env, from, `Entendido. *${achou.nome}* está associado a ${assoc[2].trim()}. Não enviei nenhuma mensagem nem iniciei cobrança.`);
    else {
      await env.HR_KV.put('comms:apelido:' + commsChaveNome(assoc[1]), assoc[2].trim(), { expirationTtl: 180 * 86400 });
      await enviar(env, from, `Entendido: ${assoc[1].trim()} é o contato de ${assoc[2].trim()}. Para enviar mensagens, preciso que compartilhe o contato dessa pessoa ou informe: *contato: ${assoc[1].trim()}, número com DDD*. Nenhuma mensagem foi enviada.`);
    }
    return true;
  }
  // Pedido natural: “avise Nome que ...”, “mande uma mensagem para Nome ...”.
  const pedido = t.match(/^(?:por favor,?\s*)?(?:avise|avisar|informe|comunique|mande(?:\s+uma)?\s+mensagem\s+para|envie(?:\s+uma)?\s+mensagem\s+para|fale\s+com)\s+(.{2,80}?)\s+(?:que\s+|:|,\s*)(.{3,3500})$/i);
  if (pedido) {
    const nome = pedido[1].trim().replace(/[.,;:]+$/, ''), corpo = pedido[2].trim();
    const contato = await commsBuscarContato(env, nome);
    if (!contato) {
      await enviar(env, from, `Ainda não tenho o número de *${nome}*. Compartilhe o cartão de contato dessa pessoa ou informe *contato: ${nome}, número com DDD*. Não enviei nada.`);
      return true;
    }
    const texto = corpo.charAt(0).toUpperCase() + corpo.slice(1);
    const rascunho = { nome: contato.nome, numero: contato.numero, texto: texto.slice(0, 4000), criado: Date.now() };
    await env.HR_KV.put('comms:rascunho:' + ultimos8(from), JSON.stringify(rascunho), { expirationTtl: 86400 });
    await enviar(env, from, `*PRÉVIA DE MENSAGEM — HR COMMS*\n\nDestinatário: ${contato.nome}\nNúmero: ${contato.numero}\n\n${rascunho.texto}\n\nNada foi enviado.\n\nResponda *APROVAR MENSAGEM* para enviar, *EDITAR MENSAGEM: novo texto* para alterar ou *CANCELAR MENSAGEM* para descartar.`);
    return true;
  }
  return false;
}

async function tratarMensagemBase(env, m, ctx) {
  const from = m.from;
  if (!from) return;

  // evita processar duas vezes a mesma mensagem (a Meta pode reenviar)
  if (m.id && !m._semRepeticao) { // v24: com o Durable Object TRAVA, o anti-repetição já foi feito nele (sem gravar no KV)
    if (await env.HR_KV.get('m:' + m.id)) return;
    await env.HR_KV.put('m:' + m.id, '1', { expirationTtl: 3600 });
  }

  if (m.type === 'reaction') return; // v23: 👍/❤️ numa mensagem é reação, não pedido (antes o cliente recebia "só leio texto")
  digitando(env, m.id);
  // Respostas do dono ao pedido de prazo e botões de aprovação valem mesmo no modo de teste (senão viravam mensagem de cliente)
  if (ehDono(env, from) && m.type !== 'audio') {
    const idB = m.type === 'interactive' ? (m.interactive?.button_reply?.id || m.interactive?.list_reply?.id || '') : '';
    if (idB.startsWith('ped_')) { await tratarBotao(env, from, idB, await getFalas(env)); return; }
    if (await tratarPrazoPedido(env, from, m)) return;
    if (await tratarPrazoAntecipado(env, from, m)) return;
  }

  let dono = ehDono(env, from);
  // Modo de teste: o dono escreve "testar cliente" e passa 30 minutos sendo tratado como cliente
  if (dono && await env.HR_KV.get('teste:cliente')) {
    if (['sair do teste', 'sair', 'parar teste', 'modo dono'].includes(normaliza(extrairTexto(m) || ''))) {
      await env.HR_KV.delete('teste:cliente');
      await env.HR_KV.delete('ca:' + from);
      await enviar(env, from, 'Modo de teste encerrado, Sr. Hangel. Voltei a atendê-lo normalmente.');
      return;
    }
    dono = false;
  }
  if (dono && m.type === 'contacts') { await commsTratarDono(env, from, 'cartão de contato', m); return; }
  if (!dono && (m.type === 'text' || m.type === 'interactive' || m.type === 'audio' || m.type === 'button') && await rhAtenderFuncionario(env, from, m, ctx).catch(e => { console.log('[RH] funcionário:', e.message); return false; })) return; // v40
  if (!dono && !atenderClientes(env)) return; // modo só-dono: ignora os demais, sem responder
  ctx.cliente = !dono;
  // v24: estas três marcas só gravam quando mudaram (antes eram 3 gravações em TODA mensagem de cliente)
  if (!dono) await kvMarcarHora(env, 'ult:' + from, 3 * 24 * 60 * 60, ULT_REGRAVAR_MS).catch(() => {});
  if (!dono && (m.type === 'audio' || m.type === 'text')) await kvGravarSeMudou(env, 'clivoz:' + ultimos8(from), m.type === 'audio' ? '1' : '0', 3 * 24 * 60 * 60).catch(() => {});
  if (!dono) await kvUltimoCliente(env, from).catch(() => {});
  if (!dono && await pvRespostaCliente(env, from, m).catch(e => { console.log('[BOT] pós-venda:', e.message); return false; })) return; // v46
  if (!dono && await tratarRetomadaCliente(env, from, m).catch(e => { console.log('[BOT] retomada cliente:', e.message); return false; })) return; // v43
  if (!dono && await tratarCobrancaCliente(env, from, m).catch(e => { console.log('[BOT] cobrança do cliente:', e.message); return false; })) return; // botões do cartão de cobrança e data de prazo
  if (!dono && await env.HR_KV.get('humano:' + from)) { await repassarAoDono(env, from, m); return; } // dono assumiu: o bot fica quieto
  if (!dono && await tratarPedidoHumano(env, from, m).catch(e => { console.log('[BOT] pedido de atendente:', e.message); return false; })) return; // v74: cliente pediu uma pessoa: liga o modo humano e avisa o dono
  if (!dono) await apresentarSePrimeira(env, from, m, ctx).catch(e => console.log('[BOT] apresentação:', e.message)); // 1ª conversa: banner + quem somos + o que fazemos
  if (!dono && m.type === 'text') { // indicação (código) e desistência: antes de qualquer outro fluxo do cliente
    const tb = String(m.text?.body || '').trim(), tm = normaliza(tb);
    if (tm) {
      await tratarIndicacaoEntrada(env, from, tb, tm).catch(e => console.log('[BOT] indicação:', e.message));
      if (await tratarDesistencia(env, from, tb, tm).catch(() => false)) return;
    }
  }
  if (!dono && await tratarMotivoPerda(env, from, m).catch(e => { console.log('[BOT] motivo da perda:', e.message); return false; })) return; // v32
  if (!dono && await tratarPosOrcamento(env, from, m)) return; // cliente com orçamento aprovado pelo dono: aprovação, pagamento, entrega

  if (dono && (m.type === 'video' || m.type === 'image') && await tratarMidiaPostDono(env, from, m).catch(e => { console.log('[ESTUDIO] mídia:', e.message); return false; })) return; // v69
  if (dono && m.type === 'image' && !String(m.image?.caption || '').trim() && await tratarPrintExtratoMP(env, from, m).catch(e => { console.log('[MPX] print do extrato:', e.message); return false; })) { await marcarUso(env, 'print_mp'); return; } // v63m
  if (dono && m.type === 'image' && await tratarFotoGeralDono(env, from, m, await getFalas(env)).catch(e => { console.log('[FOTO] dono:', e.message); return false; })) { await marcarUso(env, 'foto'); return; } // v63n
  { const vt = visionTipo(env, m, dono); // HR VISION: imagem ou PDF é recebido, registrado e confirmado (comprovante de Pix e fluxos do dono vêm antes)
    if (vt && !(await tratarVision(env, from, m, dono, vt))) return; }

  if (dono && m.type === 'image') { await tratarImagemDono(env, from, m); return; }

  if (!dono && m.type === 'location' && m.location && m.location.latitude != null) { // pino do cliente: só a localização atual vale
    if (await localizacaoAoVivoCliente(env, from, m)) return;
    ctx.loc = { lat: Number(m.location.latitude), lng: Number(m.location.longitude), nome: String(m.location.name || '').slice(0, 80), end: String(m.location.address || '').slice(0, 160) };
  }
  let bruto, voz = false;
  if (m.type === 'audio') {
    const t = m._texto || await ouvirAudio(env, from, m, dono);
    if (!t) return;
    bruto = t; voz = true; ctx.voz = true; // falou → eu respondo falando (e também em texto)
  } else if (!dono && ['image', 'video', 'document'].includes(m.type)) {
    bruto = await receberMidiaCliente(env, from, m); // foto/arquivo: vai ao dono e a IA fica sabendo
  } else {
    bruto = extrairTexto(m);
  }
  if (bruto === null || (bruto === '' && m.type !== 'text')) {
    if (m.type === 'sticker') return; // v23: figurinha é como um sorriso: não precisa de resposta
    await enviar(env, from, fala(await getFalas(env), 'soTexto', {}));
    return;
  }

  const msg = normaliza(bruto);
  if (!msg) {
    // v62: cliente que manda só "???", "?" ou emoji não fica sem resposta (antes recebia só o banner, ou nada)
    if (!dono && m.type === 'text' && String(bruto || '').trim() && atenderClientes(env) && !(await env.HR_KV.get('humano:' + from))) {
      const emConversa = await env.HR_KV.get('ca:' + from);
      if (emConversa && env.AI_KEY) { ctx.bruto = bruto; await atenderClienteIA(env, from, /^\?+$/.test(String(bruto).trim()) ? `${bruto} (o cliente não entendeu ou está esperando resposta)` : bruto, m._perfil).catch(e => console.log('[BOT] ??? na conversa:', e.message)); return; }
      if (await limiteCliente(env, from)) await enviarMenuCliente(env, from, (await lerNomeSalvo(env, from).catch(() => '')) || nomeDoPerfil(m._perfil) || '');
    }
    return;
  }
  ctx.bruto = bruto; // v48
  if (dono && pedeVoz(msg)) { voz = true; ctx.voz = true; }
  const F = await getFalas(env);

  if (dono) {
    if (await tratarApelidoFuncionario(env, from, bruto, msg).catch(e => { console.log('[BOT] apelido:', e.message); return false; })) return; // v45
    if (await tratarRecadoFuncionario(env, from, bruto, msg).catch(e => { console.log('[BOT] recado funcionário:', e.message); return false; })) return; // v44
    if (await tratarRetomadaDono(env, from, bruto, msg).catch(e => { console.log('[BOT] retomada:', e.message); return false; })) return; // v43
    if (await tratarAtenderEncaminhado(env, from, bruto, msg).catch(e => { console.log('[BOT] atender encaminhado:', e.message); return false; })) return; // v31
    if (await commsTratarDono(env, from, bruto, m)) return;
    await entregarPendentes(env, from).catch(e => console.log('[BOT] pendentes:', e.message));
    if (m.type === 'audio' && (await tratarPrazoPedido(env, from, m, bruto) || await tratarPrazoAntecipado(env, from, m, bruto))) return; // prazo dito por áudio
    if (m.type === 'interactive') {
      const idBtn = m.interactive?.button_reply?.id || m.interactive?.list_reply?.id || '';
      if (await tratarBotao(env, from, idBtn, F)) return;
    }
    if (await estComandoDono(env, from, bruto, msg)) return; // v69
    if (await igComandoDono(env, from, msg)) return; // v65
    if (await tratarAssumir(env, from, bruto, msg)) return;
    if (await tratarApelido(env, from, bruto, msg)) return;
    if (await tratarEnsino(env, from, bruto, msg)) return;
    if (await tratarFechamento(env, from, bruto, msg)) return;
    if (await tratarNotas(env, from, bruto, msg)) return;
    if (await tratarDescPendente(env, from, bruto, msg, F)) return;
    if (await tratarQR(env, from, bruto, msg)) return;
    if (await tratarAgente(env, from, msg)) return;
    if (await tratarSinal(env, from, bruto, msg)) return;
    if (await tratarLiberar(env, from, bruto, msg)) return;
    if (await tratarVincularPix(env, from, bruto, msg)) return;
    if (await tratarNumeros(env, from, bruto, msg)) return;
    if (await tratarPerfil(env, from, bruto, msg)) return;
    if (await tratarPortfolio(env, from, bruto, msg)) return;
    if (/^(dica|dicas|outra dica|me de uma dica|uma dica)$/.test(msg)) { const t = await escolherDica(env, true); await enviar(env, from, t ? `💡 ${t}` : 'Sr. Hangel, o senhor já usa tudo que eu tinha para mostrar. 👏'); return; }
    if (/^(parar|desligar|sem) dicas?$/.test(msg)) { await env.HR_KV.put('cfg:dicas', '0'); await enviar(env, from, 'Certo, Sr. Hangel: não mando mais a dica do dia. Para voltar, escreva *voltar dicas*. Para ver uma quando quiser, escreva *dica*.'); return; }
    if (/^(voltar|ligar|religar) dicas?$/.test(msg)) { await env.HR_KV.delete('cfg:dicas'); await enviar(env, from, 'Pronto, Sr. Hangel: a dica do dia volta amanhã de manhã.'); return; }
    if (/^gastos da semana$/.test(msg)) marcarUso(env, 'cmd:semana');
    { const mav = msg.match(/^(?:avaliacoes|avaliacao|notas|nota do atendimento)(?:\s+(semana|mes|hoje|\d{1,3}))?$/); if (mav) { marcarUso(env, 'cmd:avaliacoes'); await enviar(env, from, await resumoAvaliacoes(env, mav[1] || '')); return; } }
    if (['conferir', 'conferir pedidos', 'problemas', 'auditoria', 'tem algo errado'].includes(msg) && atenderClientes(env)) {
      await enviar(env, from, await comandoConferir(env));
      return;
    }
    if (RE_RESUMO_MES.test(msg)) { await enviar(env, from, await resumoMesTexto(env)); return; }
    if (['status', 'status do bot', 'saude', 'saude do bot', 'painel'].includes(msg)) {
      await enviar(env, from, await comandoStatus(env));
      return;
    }
    if (['fila', 'clientes', 'clientes ativos', 'quem esta esperando', 'quem espera'].includes(msg) && atenderClientes(env)) {
      await enviar(env, from, await comandoFila(env));
      return;
    }
    if (['leads', 'lead', 'pendentes'].includes(msg) && atenderClientes(env)) {
      await enviar(env, from, await comandoLeads(env));
      return;
    }
    if (['testar cliente', 'modo cliente', 'simular cliente'].includes(msg)) {
      await env.HR_KV.delete('ca:' + from);
      await env.HR_KV.delete('s:' + from);
      await env.HR_KV.put('teste:cliente', '1', { expirationTtl: 30 * 60 });
      await enviar(env, from, 'Modo de teste ativado por 30 minutos, Sr. Hangel. A partir de agora o tratarei como um cliente, para que veja o atendimento como ele é.\n\nPara sair, escreva *sair do teste*.');
      await env.HR_KV.put('apr2:' + ultimos8(from), '1', { expirationTtl: apresTtl(env) }).catch(() => {});
      await enviarApresentacao(env, from).catch(e => console.log('[BOT] apresentação (teste):', e.message)); // o dono vê o banner como o cliente vê
      if (env._ctx) env._ctx.apresentou = true;
      await enviarMenuCliente(env, from, null);
      return;
    }
    if (['resumo do dia', 'resumo matinal', 'resumo da manha', 'bom dia resumo', 'briefing'].includes(msg)) {
      await enviar(env, from, 'Preparando o resumo do dia, Sr. Hangel.');
      await enviarResumoMatinal(env, { refazer: true });
      return;
    }
    if (['ajuda', 'menu', 'comandos'].includes(msg)) {
      await enviarComBotoes(env, from, fala(F, 'donoOla', {}), [BTN_HOJE, BTN_Q.financas, BTN_Q.agenda]);
      return;
    }
    // Agente (Anthropic): entende a conversa toda e escolhe a ação. Comandos e lançamentos diretos continuam rápidos, sem IA.
    if (agenteAtivo(env)) {
      const olaAg = ['oi', 'ola', 'bom dia', 'boa tarde', 'boa noite', 'opa', 'ei'].some(p => msg === p || msg.startsWith(p + ' '));
      if (olaAg) { await enviarComBotoes(env, from, fala(F, 'donoOla', {}), [BTN_HOJE, BTN_Q.financas, BTN_Q.agenda]); return; }
      const ehOrc = querOrcamento(msg) || pareceDadoOrcamento(msg);
      if (!ehOrc && !pareceConsulta(bruto, msg) && lancamentoSimples(bruto) && await tratarFinancas(env, from, bruto, msg, F, voz)) return;
      await responderAgente(env, from, bruto, F, voz);
      return;
    }
    // Orçamento de soleira/peitoril: tem fluxo próprio (rascunho + perguntas fixas), sem passar pela IA geral
    if (await tratarOrcamento(env, from, bruto, msg)) return;
    const ola = ['oi', 'ola', 'bom dia', 'boa tarde', 'boa noite', 'opa', 'ei'].some(p => msg === p || msg.startsWith(p + ' '));
    // com IA ligada: perguntas vão direto para ela (evita "quanto gastei em 2026?" virar lançamento de R$ 2026)
    if (env.AI_KEY && !ola && pareceConsulta(bruto, msg)) { await responderIA(env, from, bruto, F, voz); return; }
    if (await tratarFinancas(env, from, bruto, msg, F, voz)) return;
    if (env.AI_KEY && !ola) { await responderIA(env, from, bruto, F, voz); return; } // o que não for comando nem lançamento
    // O dono nunca entra no atendimento de clientes. Para ver o atendimento como o cliente vê: "testar cliente".
    if (ola) await enviarComBotoes(env, from, fala(F, 'donoOla', {}), [BTN_HOJE, BTN_Q.financas, BTN_Q.agenda]);
    else await enviar(env, from, fala(F, 'donoNaoEntendi', {}));
    return;
  }

  // Cliente respondendo à pesquisa de satisfação
  if (await tratarPosInstalacao(env, from, bruto, msg)) return;
  if (await tratarPesquisa(env, from, bruto, msg)) return;

  // Cliente: menu de boas-vindas e botões (orçamento rápido, visita técnica, falar com a equipe)
  if (await tratarMenuCliente(env, from, m, msg)) return;

  // Cliente: a IA conduz o atendimento. Se ela falhar, pede para repetir; na 3ª falha em 10 min (ou sem AI_KEY)
  // encaminha à equipe, que recebe o aviso. O cliente nunca fica sem caminho.
  if (env.AI_KEY) {
    if (await atenderClienteIA(env, from, bruto, m._perfil)) return;
    const kf = 'iaf:' + from, nf = (Number(await env.HR_KV.get(kf)) || 0) + 1;
    await env.HR_KV.put(kf, String(nf), { expirationTtl: 600 });
    if (nf < 3) { await enviar(env, from, 'Peço desculpas, tive uma instabilidade momentânea. Pode repetir a sua última mensagem, por favor?'); return; }
  }
  await encaminharHumano(env, from, (await lerNomeSalvo(env, from)) || nomeDoPerfil(m._perfil));
}

// ── Falhas que antes eram engolidas em silêncio ──
// Vai sempre ao log do Worker. Avisa o dono no máximo 1 vez por dia por "onde" e 5 por dia no total
// (poupa o KV e o WhatsApp dele). Nunca lança erro: quem chama já estava tratando uma falha.
async function falhou(env, onde, e) {
  const msg = String((e && e.message) || e).slice(0, 160);
  console.log('[BOT] falha em ' + onde + ':', msg);
  try {
    if (String(env.PROATIVO || '1') === '0') return;
    if (/limit exceeded|too many requests|quota/i.test(msg)) return; // cota do KV: já tratada em outros pontos
    const dia = dataBahia();
    const chave = 'errbot:' + dia + ':' + onde.replace(/[^\w:]/g, '_').slice(0, 60);
    if (await env.HR_KV.get(chave)) return;
    const kn = 'errbot:n:' + dia, n = Number(await env.HR_KV.get(kn)) || 0;
    if (n >= 5) return;
    await env.HR_KV.put(chave, '1', { expirationTtl: 2 * 86400 }); // marca antes de avisar: se o aviso falhar, não entra em laço
    await env.HR_KV.put(kn, String(n + 1), { expirationTtl: 2 * 86400 });
    await notificarDono(env, Date.now(), `*Falha interna, Sr. Hangel* (${onde}): ${msg}\n\n_Aviso único por tipo, por dia. O resto do bot segue funcionando._`);
  } catch (_) {}
}

// ══════════════════════════════════════════════════════════════════════
// v24 — ECONOMIA DO KV (o plano grátis permite 1.000 gravações por dia)
// Antes: ~9 gravações por mensagem de cliente. Agora: ~4.
//  1. ult:/clivoz:/ultcli só gravam quando mudaram (ult: no máximo a cada 10 min: a janela de 24 h fica até 10 min mais curta, nunca mais longa)
//  2. cfg:self (endereço do Worker) só grava quando muda
//  3. limite diário por cliente (rl:) conta na memória e grava a cada 10 mensagens
//  4. conversas (ca:) levam um resumo em metadados: a varredura das avaliações pula sem ler o que não tem nada a fazer
//  5. TRAVA (opcional, Durable Object): trava por cliente e anti-repetição sem gastar o KV. Sem o binding, tudo segue no KV como antes
// ══════════════════════════════════════════════════════════════════════
const ULT_REGRAVAR_MS = 10 * 60 * 1000;
async function kvMarcarHora(env, k, ttl, minMs) {
  const ant = Number(await env.HR_KV.get(k)) || 0;
  if (ant && Date.now() - ant < minMs) return false;
  await env.HR_KV.put(k, String(Date.now()), { expirationTtl: ttl });
  return true;
}
async function kvGravarSeMudou(env, k, v, ttl) {
  if ((await env.HR_KV.get(k)) === v) return false;
  await env.HR_KV.put(k, v, { expirationTtl: ttl });
  return true;
}
async function kvUltimoCliente(env, from) {
  let ant = null; try { ant = JSON.parse((await env.HR_KV.get('ultcli')) || 'null'); } catch (_) {}
  if (ant && ant.numero === from && Date.now() - (Number(ant.hora) || 0) < 60 * 60 * 1000) return false;
  await env.HR_KV.put('ultcli', JSON.stringify({ numero: from, hora: Date.now() }), { expirationTtl: 24 * 60 * 60 });
  return true;
}

// Resumo da conversa nos metadados da chave ca: (a listagem do KV devolve isso sem ler o valor)
function metaConversa(v) {
  let c = null; try { c = JSON.parse(v); } catch (_) { return null; }
  if (!c || typeof c !== 'object') return null;
  const hist = Array.isArray(c.hist) ? c.hist : null;
  return {
    v: 1, u: Number(c.ultimaEm) || 0, h: hist ? 1 : 0,
    n: hist ? hist.filter(x => x && x.role === 'user').length : 0,
    c: c.concluido ? 1 : 0, a: c.avalPedida ? 1 : 0, r: c.resumoDono ? 1 : 0, t: c.retomadaEm ? 1 : 0,
    i: (c.dados && INTERESSES[c.dados.interesse]) ? 1 : 0,
  };
}
// true = com certeza não há nada a fazer com esta conversa agora (mesmas regras de pedirAvaliacoes). Na dúvida, false (lê a conversa)
function avalPodePular(md, agora) {
  if (!md || md.v !== 1) return false; // chave antiga, sem resumo: lê como antes
  if (!md.u || !md.h) return true;
  if (md.n < 2) return true;
  const ocioso = agora - md.u;
  if (ocioso < Math.min(AVAL_OCIOSO_MS, AVAL_RETOMADA_MS)) return true; // cedo demais para qualquer coisa
  if (!md.r && !md.c && ocioso >= AVAL_OCIOSO_MS && ocioso <= 3 * 86400000) return false; // aviso "parou de responder" ao dono
  if (md.a) return true;                                                 // nota já pedida
  if (!md.c && md.i) return !(!md.t && ocioso >= AVAL_RETOMADA_MS && ocioso <= AVAL_JANELA_MS); // só a retomada poderia sair
  return false;                                                          // pedido de nota: depende do pedido, lê
}

// Embrulha o KV: toda gravação de conversa (ca:) leva os metadados. O resto passa direto.
function comKV(env) {
  const kv = env && env.HR_KV;
  if (!kv || kv.__hr24) return env;
  const w = {
    __hr24: true,
    get: (...a) => kv.get(...a),
    getWithMetadata: (...a) => kv.getWithMetadata(...a),
    list: (...a) => kv.list(...a),
    delete: (...a) => kv.delete(...a),
    put(k, v, o) {
      if (typeof k === 'string' && k.startsWith('ca:') && typeof v === 'string') {
        const md = metaConversa(v);
        if (md) o = { ...(o || {}), metadata: md };
      }
      return kv.put(k, v, o);
    },
  };
  const e = Object.create(env);
  e.HR_KV = w;
  return e;
}

// ── Durable Object TRAVA (opcional): fila por cliente + anti-repetição da Meta, sem gravar no KV ──
// Só vale se um dia o Worker for publicado pelo wrangler com o binding TRAVA (a classe não vai neste arquivo: o painel não cria Durable Object). Sem ele, nada muda.
function travaDO(env, from) {
  try { return env.TRAVA ? env.TRAVA.get(env.TRAVA.idFromName('c:' + ultimos8(from))) : null; } catch (_) { return null; }
}
async function travaDOChamar(stub, acao, dados) {
  const r = await stub.fetch('https://trava/' + acao, { method: 'POST', body: JSON.stringify(dados || {}) });
  if (!r.ok) throw new Error('TRAVA ' + acao + ' ' + r.status);
  return r.json();
}
// libera o id para a Meta reenviar (usado quando o tratamento falhou)
async function esquecerMensagem(env, m) {
  if (!m || !m.id) return;
  const st = travaDO(env, m.from);
  if (st) await travaDOChamar(st, 'esquecer', { id: m.id }).catch(() => {});
  await env.HR_KV.delete('m:' + m.id).catch(() => {});
}

// Uma mensagem por cliente de cada vez: duas mensagens seguidas chegam como dois avisos simultâneos da Meta e
// antes se pisavam (pedido sobrescrito). Com o Durable Object TRAVA, a fila e o anti-repetição ficam nele (garantido e sem KV).
// Sem ele (ou se ele falhar), trava no KV, melhor esforço: se o KV falhar, segue sem travar.
async function comTrava(env, from, fn, m) {
  const st = travaDO(env, from);
  if (st) {
    let r = null;
    try { r = await travaDOChamar(st, 'entrar', { id: (m && m.id) || '' }); } catch (e) { console.log('[BOT] TRAVA indisponível, usando o KV:', e.message); }
    if (r) {
      if (r.dup) return;                 // a Meta reenviou a mesma mensagem: já tratada
      if (m) m._semRepeticao = true;     // tratarMensagemBase não precisa gravar m: no KV
      try { return await fn(); }
      finally { await travaDOChamar(st, 'sair', { token: r.token }).catch(() => {}); }
    }
  }
  const k = 'trv:' + ultimos8(from);
  for (let i = 0; i < 8; i++) { // espera até ~8 s a mensagem anterior terminar
    let t = null;
    try { t = await env.HR_KV.get(k); } catch (_) { break; }
    if (!t || Date.now() - Number(t) > 45000) break; // livre, ou trava velha demais
    await new Promise(r => setTimeout(r, 1000));
  }
  try { await env.HR_KV.put(k, String(Date.now()), { expirationTtl: 60 }); } catch (_) {}
  try { return await fn(); }
  finally { await env.HR_KV.delete(k).catch(() => {}); }
}

async function tratarPayload(env, payload) {
  if (!env._depois) env._depois = new Map(); // v27: pedidos que o bot confere depois de dar tempo ao app (fora da trava do cliente)
  for (const entry of payload?.entry || []) {
    for (const ch of entry.changes || []) {
      const perfis = {};
      for (const c of ch.value?.contacts || []) if (c.wa_id) perfis[c.wa_id] = c.profile?.name || '';
      for (const st of ch.value?.statuses || []) { // entregue / lida / falhou (só as cobranças acompanhadas geram aviso)
        try { await tratarStatusEntrega(env, st); } catch (e) { console.log('[BOT] status de entrega:', e.message); }
      }
      for (const m of ch.value?.messages || []) {
        m._perfil = perfis[m.from] || '';
        try { await comTrava(env, m.from, () => tratarMensagem(env, m), m); }
        catch (e) {
          console.log('[BOT] erro ao tratar mensagem:', e.message);
          await esquecerMensagem(env, m); // libera o id (TRAVA e KV): um reenvio da Meta volta a ser tratado
          if (!ehDono(env, m.from)) { // cliente nunca fica sem resposta em silêncio: o dono é avisado com o texto e o link
            const txt = m.type === 'text' ? String(m.text?.body || '').slice(0, 200) : '[' + m.type + ']';
            const aviso = `*Falha ao atender ${m._perfil || 'um cliente'}:* não consegui processar a mensagem (${String(e.message).slice(0, 80)}).\n"${txt}"\nwa.me/${normalizarBR(m.from)}`;
            await notificarDono(env, Date.now(), aviso).catch(() => enviarTextoPuro(env, numeroDono(env), aviso).catch(() => {}));
          }
          // O dono nunca fica no silêncio: o envio direto não usa o KV, então funciona mesmo com a cota do KV estourada.
          if (ehDono(env, m.from)) {
            const kv = /limit exceeded|too many requests|quota/i.test(String(e.message));
            await enviarTextoPuro(env, m.from, kv
              ? 'Sr. Hangel, o armazenamento do Worker atingiu o limite diário e não consigo processar seu pedido agora. Ele volta a funcionar às 21h (horário da Bahia).'
              : 'Sr. Hangel, tive um problema interno ao processar sua mensagem. Tente novamente em instantes.\n\n_Detalhe: ' + String(e.message).slice(0, 120) + '_').catch(() => {});
          }
        }
      }
    }
  }
  await pedirAvaliacoes(env); // sem depender do gatilho agendado: confere quem parou de responder (no máximo a cada 5 minutos)
  await rodarDepois(env).catch(e => falhou(env, 'bot no lugar do app', e)); // v27
}

// ── Segurança: confere que o aviso veio mesmo da Meta ────────────────
// ═════════════════════════════════════════════════════════════════════════════
// v64: INSTAGRAM (@ da HR) — Direct respondido pela IA + comentários "quanto custa?" respondidos sozinhos.
//   API do Instagram com login do Instagram (graph.instagram.com). Configuração pelo app (Config → Instagram) ou variáveis:
//   IG_TOKEN (token de longa duração da conta), IG_APP_SECRET (chave secreta do app do Instagram, para conferir o webhook).
//   O webhook é o mesmo /webhook do WhatsApp (objeto "instagram"). INSTAGRAM=0 desliga. IG_COMENTARIOS=0 desliga os comentários.
//   Objetivo do Direct: responder rápido, entender o que a pessoa quer e levar para o WhatsApp (link com mensagem pronta),
//   onde o atendimento completo (medidas, orçamento, visita) já funciona.
// ═════════════════════════════════════════════════════════════════════════════
const IG_API = 'https://graph.instagram.com/v23.0';
async function igToken(env) { return (await env.HR_KV.get('ig:token')) || env.IG_TOKEN || ''; }
async function igSegredo(env) { return (await env.HR_KV.get('ig:segredo')) || env.IG_APP_SECRET || ''; }
function igAtivo(env) { return String(env.INSTAGRAM || '1') !== '0'; }
async function igApi(env, caminho, opts = {}) {
  const tk = await igToken(env); if (!tk) throw new Error('Instagram sem token');
  const sep = caminho.includes('?') ? '&' : '?';
  const r = await fetch(`${IG_API}${caminho}${opts.method && opts.method !== 'GET' ? '' : sep + 'access_token=' + encodeURIComponent(tk)}`, {
    method: opts.method || 'GET',
    headers: opts.body ? { 'Content-Type': 'application/json', Authorization: 'Bearer ' + tk } : { Authorization: 'Bearer ' + tk },
    body: opts.body ? JSON.stringify(opts.body) : undefined,
  });
  const j = await r.json().catch(() => null);
  if (!r.ok) throw new Error(`Instagram ${r.status}: ${String((j && j.error && j.error.message) || 'erro').slice(0, 200)}`);
  return j;
}
async function igEu(env) {
  try { const c = JSON.parse((await env.HR_KV.get('ig:eu')) || 'null'); if (c && c.id) return c; } catch (_) {}
  const j = await igApi(env, '/me?fields=user_id,username,name');
  const eu = { id: String(j.user_id || j.id), username: j.username || '', name: j.name || '' };
  await env.HR_KV.put('ig:eu', JSON.stringify(eu), { expirationTtl: 7 * 86400 });
  return eu;
}
async function igNumeroWhats(env) { return String(env.WHATSAPP_PUBLICO || '').replace(/\D/g, '') || (await pontoBotNumero(env).catch(() => '')) || ''; }
// "5574999998888" → "(74) 99999-8888"
async function igWhatsFormatado(env) {
  const n = await igNumeroWhats(env); const d = n.replace(/^55/, '');
  if (d.length === 11) return `(${d.slice(0, 2)}) ${d.slice(2, 7)}-${d.slice(7)}`;
  if (d.length === 10) return `(${d.slice(0, 2)}) ${d.slice(2, 6)}-${d.slice(6)}`;
  return n ? '+' + n : '';
}
async function igLinkWhats(env, texto) {
  const n = await igNumeroWhats(env);
  return n ? `https://wa.me/${n}?text=${encodeURIComponent(texto)}` : '';
}
// ── v65: ASSISTENTE PROFISSIONAL DO INSTAGRAM ─────────────────────────────────
//   Direct: marca como visto e mostra "digitando…", entende texto, FOTO (descreve com a IA), ÁUDIO (transcreve), resposta a STORY,
//   publicação compartilhada; responde com botões de resposta rápida e, na hora certa, com o BOTÃO "Falar no WhatsApp"
//   (mensagem pronta com o pedido) e "Ver pedras e trabalhos" (catálogo do site). Perguntas frequentes (ice breakers) no Direct.
