    const k = 'vh:' + ultimos8(body.numero);
    let alvo = null; try { alvo = JSON.parse((await env.HR_KV.get(k)) || 'null'); } catch (_) {}
    if (!alvo || !alvo.numero) return jsonR({ ok: false, error: 'Esse cliente não está esperando horários (já respondido ou expirado).' }, 404);
    alvo._k = k;
    let itens = [];
    if (Array.isArray(body.horarios)) itens = body.horarios.filter(h => h && /^\d{4}-\d{2}-\d{2}$/.test(String(h.dia)) && horaParaMin(h.hora) !== null).map(h => ({ dia: h.dia, hm: horaParaMin(h.hora) }));
    else itens = lerHorariosDono(String(body.texto || ''));
