// v49 · PÁGINA DE PAGAMENTO DA HR (/pagar/<ref>)
// Mostra a marca da empresa (nunca nome de pessoa), o valor, o Pix (QR + copia e cola) e o botão do cartão,
// que abre o checkout do Mercado Pago. Quando o pagamento cai, a página mostra "Pagamento confirmado".
// ══════════════════════════════════════════════════════════════════════
async function rotaPagar(req, env, url) {
  const partes = url.pathname.split('/').filter(Boolean); // ['pagar', ref, ('status')?]
  const ref = String(partes[1] || '').replace(/[^a-z0-9-]/gi, '').slice(0, 40);
  let lk = null; try { lk = JSON.parse((await env.HR_KV.get('lk:' + ref)) || 'null'); } catch (_) {}
  if (partes[2] === 'status') return new Response(JSON.stringify({ pago: !!(lk && lk.pago) }), { headers: { 'content-type': 'application/json', 'cache-control': 'no-store' } });
  const esc = t => String(t == null ? '' : t).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const empresa = env.EMPRESA || 'HR Mármores e Granitos';
  const [e1, ...eR] = empresa.split(' ');
  if (!lk) return new Response(`<!DOCTYPE html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(empresa)}</title></head><body style="font-family:system-ui;background:#0f0c00;color:#eee;text-align:center;padding:60px 20px"><h2 style="color:#C9A84C">${esc(empresa)}</h2><p>Esta cobrança não existe mais ou já venceu.<br>Fale com a gente pelo WhatsApp para receber um novo link.</p></body></html>`, { status: 404, headers: { 'content-type': 'text/html; charset=utf-8' } });
  const qr = lk.codigo ? await env.HR_KV.get('lkqr:' + ref) : null;
  const protocolo = 'HR-' + ref.replace(/^lk-/, '').toUpperCase();
  const venc = lk.em ? new Date(lk.em + 7 * 86400000).toLocaleDateString('pt-BR', { timeZone: 'America/Bahia' }) : '';
  const pixVence = lk.em && Date.now() > lk.em + 24 * 3600000;
  const cnpj = env.EMPRESA_CNPJ ? `CNPJ ${esc(env.EMPRESA_CNPJ)}` : '';
  const html = `<!DOCTYPE html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Pagamento · ${esc(empresa)}</title><meta name="theme-color" content="#0f0c00">
<meta property="og:title" content="Pagamento · ${esc(empresa)}"><meta property="og:description" content="R$ ${reais(lk.valor)} — ${esc(lk.desc)}">
<style>
*{box-sizing:border-box}body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;background:#f4efe4;color:#222}
.top{background:#0f0c00;padding:26px 20px 70px;text-align:center;border-bottom:3px solid #C9A84C}
.marca{font-size:13px;letter-spacing:4px;color:#C9A84C;font-weight:800}.marca2{font-size:24px;color:#fff;font-weight:800;margin-top:2px}
.sub{font-size:10px;letter-spacing:3px;color:rgba(201,168,76,.7);margin-top:6px}
.card{max-width:440px;margin:-52px auto 16px;background:#fff;border-radius:18px;box-shadow:0 10px 30px rgba(0,0,0,.12);overflow:hidden}
.val{padding:22px 20px 18px;text-align:center;border-bottom:1px solid #eee5d0;background:linear-gradient(180deg,#fffdf7,#fbf4e2)}
.lbl{font-size:10px;letter-spacing:3px;color:#a8862e;font-weight:800;text-transform:uppercase}
.preco{font-size:42px;font-weight:900;color:#7a4400;letter-spacing:-1px;margin:6px 0 4px}.desc{font-size:15px;color:#444}
.prot{font-size:11px;color:#999;margin-top:8px}
.sec{padding:18px 20px;border-bottom:1px solid #f0ead8}.sec h3{margin:0 0 10px;font-size:16px;color:#3a2000}
.qr{display:block;width:210px;height:210px;margin:6px auto 12px;border:1px solid #eee;border-radius:12px;padding:8px;background:#fff}
.cod{font-family:ui-monospace,monospace;font-size:11px;word-break:break-all;background:#f7f3ea;border:1px dashed #d8c99c;border-radius:10px;padding:10px;color:#555;max-height:72px;overflow:hidden}
.bt{display:block;width:100%;border:0;border-radius:12px;padding:15px;font-size:16px;font-weight:800;cursor:pointer;text-align:center;text-decoration:none;margin-top:10px}
.ouro{background:linear-gradient(135deg,#d9b95c,#C9A84C);color:#1a1200}.esc{background:#0f0c00;color:#C9A84C}
.passo{font-size:13px;color:#666;line-height:1.6;margin-top:10px}
.ok{display:none;padding:34px 20px;text-align:center}.ok .ic{width:70px;height:70px;border-radius:50%;background:#2e7d32;color:#fff;font-size:40px;line-height:70px;margin:0 auto 12px}
.rod{text-align:center;font-size:11px;color:#9a8c6a;padding:6px 20px 30px;line-height:1.6}
.seg{display:flex;align-items:center;justify-content:center;gap:6px;font-size:12px;color:#2e7d32;font-weight:700;padding:12px}
</style></head><body>
<div class="top"><div class="marca">${esc(e1.toUpperCase())}</div><div class="marca2">${esc(eR.join(' ') || '')}</div><div class="sub">MÁRMORE · GRANITO · QUARTZITO</div></div>
<div class="card">
 <div class="val"><div class="lbl">Valor a pagar</div><div class="preco">R$ ${reais(lk.valor)}</div><div class="desc">${esc(lk.desc)}</div><div class="prot">Protocolo ${protocolo}${venc ? ' · válido até ' + venc : ''}</div></div>
 <div id="ok" class="ok"><div class="ic">✓</div><h2 style="margin:0 0 6px;color:#2e7d32">Pagamento confirmado</h2><div style="color:#555">Obrigado! A ${esc(empresa)} já recebeu o seu pagamento.</div></div>
 <div id="pagar">
 ${lk.codigo && !pixVence ? `<div class="sec"><h3>💠 Pagar com Pix</h3>
  ${qr ? `<img class="qr" alt="QR Code Pix" src="data:image/png;base64,${qr}">` : ''}
  <div class="cod" id="cod">${esc(lk.codigo)}</div>
  <button class="bt ouro" id="cp">Copiar código Pix</button>
  <div class="passo">No app do seu banco, escolha <b>Pix › Pix Copia e Cola</b>, cole o código e confirme. A confirmação aparece aqui na hora.</div></div>` : ''}
 ${lk.mp ? `<div class="sec"><h3>💳 Pagar com cartão</h3><a class="bt esc" href="${esc(lk.mp)}">Pagar com cartão de crédito</a><div class="passo">Você vai para o ambiente seguro do Mercado Pago para digitar os dados do cartão.</div></div>` : ''}
 </div>
 <div class="seg">🔒 Pagamento processado com segurança pelo Mercado Pago</div>
</div>
<div class="rod"><b>${esc(empresa)}</b>${cnpj ? '<br>' + cnpj : ''}<br>Dúvidas? Responda a nossa conversa no WhatsApp.</div>
<script>
var cp=document.getElementById('cp');if(cp)cp.onclick=function(){var t=document.getElementById('cod').textContent;
 function feito(){cp.textContent='✓ Código copiado!';setTimeout(function(){cp.textContent='Copiar código Pix';},2500);}
 if(navigator.clipboard)navigator.clipboard.writeText(t).then(feito,function(){prompt('Copie o código:',t);});else prompt('Copie o código:',t);};
function ver(){fetch(location.pathname.replace(/\\/$/,'')+'/status',{cache:'no-store'}).then(function(r){return r.json();}).then(function(j){if(j.pago){document.getElementById('pagar').style.display='none';document.getElementById('ok').style.display='block';}else setTimeout(ver,5000);}).catch(function(){setTimeout(ver,8000);});}
${lk.pago ? "document.getElementById('pagar').style.display='none';document.getElementById('ok').style.display='block';" : 'setTimeout(ver,4000);'}
</script></body></html>`;
  return new Response(html, { headers: { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-store' } });
}
// ══════════════════════════════════════════════════════════════════════
// v50 · SITE "MONTE O SEU PROJETO" (/portfolio)
// O cliente escolhe ambiente → pedra → cuba → acessórios, deixa nome e WhatsApp e envia. O bot avisa o Sr. Hangel,
// já deixa a conversa do cliente com as escolhas (a secretária continua sem perguntar de novo) e abre o WhatsApp do cliente.
// Dados: o catalogo.json que o app publica no GitHub (CATALOGO_JSON_URL; padrão: o repositório do app). Sem ele, usa as pedras do bot.
// ══════════════════════════════════════════════════════════════════════
const CATALOGO_JSON_PADRAO = 'https://raw.githubusercontent.com/hrmarmoresegranitos5-jpg/Hr/main/catalogo.json';
let _siteCat = null, _siteCatEm = 0;
async function siteLerCatalogo(env) {
  if (_siteCat && Date.now() - _siteCatEm < 10 * 60000) return _siteCat;
  try {
    const r = await fetch(env.CATALOGO_JSON_URL || CATALOGO_JSON_PADRAO, { cf: { cacheTtl: 300, cacheEverything: true } });
    if (!r.ok) throw new Error('HTTP ' + r.status);
    const j = await r.json();
    if (j && Array.isArray(j.pedras)) { _siteCat = j; _siteCatEm = Date.now(); }
  } catch (e) { console.log('[SITE] catálogo:', e.message); }
  return _siteCat;
}
function siteFoto(it) {
  if (!it) return '';
  let f = it.photo || '';
  if (!f) { let l = it.fotos; if (typeof l === 'string') { try { l = JSON.parse(l); } catch (_) { l = []; } } if (Array.isArray(l) && l.length) f = l[0]; }
  return /^data:image\/|^https:\/\//.test(String(f)) ? String(f) : '';
}
const SITE_GRUPOS = { pedra: 'pedras', coz: 'cubas_coz', lav: 'cubas_lav', acess: 'acessorios' };
async function siteLeadsLista(env) {
  const out = [];
  let cur;
  do {
    const r = await env.HR_KV.list({ prefix: 'site:lead:', cursor: cur });
    for (const k of r.keys) { try { const l = JSON.parse((await env.HR_KV.get(k.name)) || 'null'); if (l && l.status !== 'arquivado') out.push(l); } catch (_) {} }
    cur = r.list_complete ? null : r.cursor;
  } while (cur && out.length < 200);
  out.sort((a, b) => b.em - a.em);
  return { ok: true, leads: out.slice(0, 60) };
}
// link pessoal do site: /portfolio?c=<token> já sabe quem é o cliente (o bot manda esse link na conversa)
async function siteLinkPessoal(env, numero, nome) {
  const base = await urlDoWorker(env).catch(() => '');
  if (!/^https:/.test(base)) return '';
  const tel = normalizarBR(String(numero || '').replace(/\D/g, ''));
  if (!tel) return base + '/portfolio';
  let t = await env.HR_KV.get('site:tokn:' + tel);
  if (!t) { t = Math.random().toString(36).slice(2, 8) + Date.now().toString(36).slice(-3); await env.HR_KV.put('site:tokn:' + tel, t, { expirationTtl: 25 * 86400 }); }
  await env.HR_KV.put('site:tok:' + t, JSON.stringify({ tel, nome: String(nome || '').slice(0, 60) }), { expirationTtl: 30 * 86400 });
  return base + '/portfolio?c=' + t;
}
async function siteObras(env, pedras) {
  const l = (await lerPortfolio(env)).filter(i => i && i.tipo === 'trabalho' && i.origem !== 'app');
  const gen = new Set(['granito', 'marmore', 'quartzito', 'pedra', 'de', 'do', 'da', 'e']);
  const chaves = pedras.map(p => ({ id: p.id, ws: normaliza(p.nm).split(' ').filter(w => w.length > 2 && !gen.has(w)) })).filter(x => x.ws.length);
  return l.slice(-60).map(i => {
    const t = normaliza(i.legenda || '');
    const pe = chaves.filter(c => c.ws.every(w => t.includes(w))).sort((a, b) => b.ws.length - a.ws.length);
    const porId = i.pedraId && pedras.some(p => p.id === i.pedraId) ? i.pedraId : '';
    return { id: i.id, cat: i.cat || '', legenda: String(i.legenda || '').slice(0, 160), pedra: porId || (pe.length ? pe[0].id : '') };
  }).reverse();
}
async function siteCatalogo(env, ctx, url) {
  const cab = { 'Access-Control-Allow-Origin': '*', 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' };
  const cat = await siteLerCatalogo(env);
  const preco = String(env.PORTFOLIO_PRECO ?? '1') !== '0';
  const n = v => { v = Number(String(v || '').replace(',', '.')); return Number.isFinite(v) && v > 0 ? Math.round(v * 100) / 100 : 0; };
  let popT = {};
  try { const pop = JSON.parse((await env.HR_KV.get('cfg:pop')) || '{}') || {}; for (const m of Object.values(pop)) for (const [nome, q] of Object.entries(m || {})) { const k = normaliza(nome); popT[k] = (popT[k] || 0) + (Number(q) || 0); } } catch (_) {}
  const fixas = String(env.PORTFOLIO_DESTAQUES || '').split(/[,;\n]/).map(x => normaliza(x)).filter(Boolean);
  let pedras = [], cubas_coz = [], cubas_lav = [], acessorios = [];
  if (cat) {
    pedras = cat.pedras.filter(x => x && x.nm && !x.oculto).map(x => ({ id: String(x.id), nm: String(x.nm).trim().slice(0, 60), cat: String(x.cat || '').slice(0, 40), fin: String(x.fin || '').slice(0, 30), desc: String(x.desc || '').slice(0, 600), pr: preco ? n(x.pr) : 0, foto: !!siteFoto(x) }));
    const item = x => ({ id: String(x.id), nm: String(x.nm || '').trim().slice(0, 60), brand: String(x.brand || x.marca || '').slice(0, 30), dim: String(x.dim || '').slice(0, 40), desc: String(x.desc || x.titulo || '').slice(0, 400), pr: preco ? n(x.pr) : 0, foto: !!siteFoto(x) });
    cubas_coz = (cat.cubas_coz || []).filter(x => x && x.nm).map(item);
    cubas_lav = (cat.cubas_lav || []).filter(x => x && x.nm).map(item);
    acessorios = (cat.acessorios || []).filter(x => x && x.nm).map(item);
  } else { // sem o catálogo do GitHub: só as pedras do bot
    for (const i of await lerPortfolio(env)) if (i && i.tipo === 'pedra' && i.nome && !pedras.some(p => normaliza(p.nm) === normaliza(i.nome)))
      pedras.push({ id: 'pf:' + i.id, nm: String(i.nome).slice(0, 60), cat: String(i.tp || '').slice(0, 40), fin: String(i.acab || '').slice(0, 30), desc: String(i.desc || '').slice(0, 600), pr: preco ? n(i.preco) : 0, foto: !i.semFoto });
  }
  const nota = p => (popT[normaliza(p.nm)] || 0) + (fixas.includes(normaliza(p.nm)) ? 100000 - fixas.indexOf(normaliza(p.nm)) : 0);
  pedras.sort((a, b) => (b.foto - a.foto) || (nota(b) - nota(a)) || a.nm.localeCompare(b.nm, 'pt-BR'));
  pedras.filter(p => nota(p) > 0).sort((a, b) => nota(b) - nota(a)).slice(0, 6).forEach(p => { p.top = 1; });
  const e = (cat && cat.emp) || {};
  const corpo = {
    empresa: env.EMPRESA || e.nome || 'HR Mármores e Granitos', cnpj: env.EMPRESA_CNPJ || '', preco, estimativa: String(env.SITE_ESTIMATIVA ?? '1') !== '0',
    whatsapp: String(env.WHATSAPP_PUBLICO || '').replace(/\D/g, '') || await pontoBotNumero(env),
    emp: { end: e.end || '', cidade: e.cidade || '', horario: e.horario || '', tel: e.tel || '', ig: e.ig || '' },
    pedras, cubas_coz, cubas_lav, acessorios,
  };
  try { corpo.obras = await siteObras(env, pedras); } catch (_) { corpo.obras = []; }
  const tok = url && String(url.searchParams.get('c') || '').replace(/[^a-z0-9]/gi, '');
  if (tok) { try { const x = JSON.parse((await env.HR_KV.get('site:tok:' + tok)) || 'null'); if (x) corpo.cliente = { nome: x.nome || '', tel: String(x.tel).replace(/^55/, '') }; } catch (_) {} }
  return new Response(JSON.stringify(corpo), { headers: cab });
}
async function siteImagem(env, ctx, url, p) {
  const cab = { 'Access-Control-Allow-Origin': '*' };
  const cache = caches.default, chave = new Request(url.toString(), { method: 'GET' });
  const emCache = await cache.match(chave); if (emCache) return emCache;
  const [, , , g, idEnc] = p.split('/'); const id = decodeURIComponent(idEnc || '');
  let f = '';
  if (g === 'pedra' && id.startsWith('pf:')) {
    const pid = id.slice(3), buf = await env.HR_KV.get('pf:img:' + pid, 'arrayBuffer');
    if (!buf) return new Response('Sem foto', { status: 404, headers: cab });
    const resp = new Response(buf, { headers: { ...cab, 'Content-Type': 'image/jpeg', 'Cache-Control': 'public, max-age=86400' } });
    ctx.waitUntil(cache.put(chave, resp.clone())); return resp;
  }
  if (g === 'obra') {
    const buf = await env.HR_KV.get('pf:img:' + id.replace(/[^a-z0-9]/gi, ''), 'arrayBuffer');
    if (!buf) return new Response('Sem foto', { status: 404, headers: cab });
    const resp = new Response(buf, { headers: { ...cab, 'Content-Type': 'image/jpeg', 'Cache-Control': 'public, max-age=86400' } });
    ctx.waitUntil(cache.put(chave, resp.clone())); return resp;
  }
  const cat = await siteLerCatalogo(env);
  if (g === 'logo') f = String((cat && cat.emp && cat.emp.logoUrl) || '');
  else if (SITE_GRUPOS[g] && cat) f = siteFoto((cat[SITE_GRUPOS[g]] || []).find(x => x && String(x.id) === id));
  if (/^https:\/\//.test(f)) return Response.redirect(f, 302);
  const m = f.match(/^data:(image\/[a-z+]+);base64,(.+)$/);
  if (!m) return new Response('Sem foto', { status: 404, headers: cab });
  const bytes = Uint8Array.from(atob(m[2]), c => c.charCodeAt(0));
  const resp = new Response(bytes, { headers: { ...cab, 'Content-Type': m[1], 'Cache-Control': 'public, max-age=86400' } });
  ctx.waitUntil(cache.put(chave, resp.clone()));
  return resp;
}
const SITE_AMB = { cozinha: 'Cozinha', banheiro: 'Banheiro', lavabo: 'Lavabo', area_servico: 'Área de serviço', varanda: 'Churrasqueira / varanda', escada: 'Escada', soleira: 'Soleira / peitoril', piso: 'Piso / revestimento', outro: 'Outro' };
async function sitePedido(req, env, ctx) {
  const cab = { 'Access-Control-Allow-Origin': '*', 'Content-Type': 'application/json; charset=utf-8' };
  const resp = (o, st) => new Response(JSON.stringify(o), { status: st || 200, headers: cab });
  if (req.method !== 'POST') return resp({ ok: false, erro: 'Método não permitido' }, 405);
  let b = null; try { b = await req.json(); } catch (_) {}
  if (!b) return resp({ ok: false, erro: 'Dados inválidos.' }, 400);
  let doLink = null; // veio pelo link pessoal que o bot mandou no WhatsApp
  const tok = String(b.c || '').replace(/[^a-z0-9]/gi, '');
  if (tok) { try { doLink = JSON.parse((await env.HR_KV.get('site:tok:' + tok)) || 'null'); } catch (_) {} }
  if (doLink) { b.tel = b.tel || doLink.tel; b.nome = b.nome || doLink.nome; }
  const t = (v, n) => String(v == null ? '' : v).replace(/[\u0000-\u001f]+/g, ' ').replace(/\s+/g, ' ').trim().slice(0, n);
  const nome = t(b.nome, 60), cidade = t(b.cidade, 50), medidas = t(b.medidas, 400), obs = t(b.obs, 400);
  let tel = String(b.tel || '').replace(/\D/g, ''); if (tel.length === 10 || tel.length === 11) tel = '55' + tel;
  if (nome.length < 2) return resp({ ok: false, erro: 'Escreva o seu nome.' });
  if (!/^55\d{10,11}$/.test(tel)) return resp({ ok: false, erro: 'Confira o seu WhatsApp com DDD.' });
  tel = normalizarBR(tel);
  // limite: 6 envios por hora por endereço e 3 por telefone (evita abuso)
  const ip = req.headers.get('cf-connecting-ip') || 'x', hora = Math.floor(Date.now() / 3600000);
  for (const k of [`site:lim:ip:${ip}:${hora}`, `site:lim:tel:${tel}:${hora}`]) {
    const q = +(await env.HR_KV.get(k)) || 0;
    if (q >= (k.includes(':ip:') ? 6 : 3)) return resp({ ok: false, erro: 'Recebemos vários envios seguidos. Fale com a gente pelo WhatsApp.' }, 429);
    await env.HR_KV.put(k, String(q + 1), { expirationTtl: 3700 });
  }
  const amb = SITE_AMB[b.ambiente] ? b.ambiente : 'outro';
  const cat = await siteLerCatalogo(env);
  const n = v => { v = Number(String(v || '').replace(',', '.')); return Number.isFinite(v) && v > 0 ? v : 0; };
  const acha = (g, id) => (cat && id ? (cat[SITE_GRUPOS[g]] || []).find(x => x && String(x.id) === String(id)) : null);
  let pedra = b.pedra && b.pedra.id ? acha('pedra', b.pedra.id) : null;
  if (!pedra && b.pedra && String(b.pedra.id).startsWith('pf:')) { const i = (await lerPortfolio(env)).find(x => x && 'pf:' + x.id === b.pedra.id); if (i) pedra = { nm: i.nome, cat: i.tp, pr: i.preco }; }
  const cuba = b.cuba && b.cuba.id ? acha(b.cuba.g === 'lav' ? 'lav' : 'coz', b.cuba.id) : null;
  const acess = (Array.isArray(b.acessorios) ? b.acessorios : []).slice(0, 20).map(id => acha('acess', id)).filter(Boolean);
  const cubaOp = t(b.cubaOp, 30);
  const protocolo = 'SITE-' + Date.now().toString(36).slice(-5).toUpperCase();
  const lead = { protocolo, em: Date.now(), status: 'novo', nome, tel, cidade, ambiente: amb, medidas, obs, pedraId: pedra && pedra.id ? String(pedra.id) : '', cubaId: cuba ? String(cuba.id) : '', cubaG: b.cuba && b.cuba.g === 'lav' ? 'lav' : 'coz', acessIds: acess.map(x => String(x.id)),
    pedra: pedra ? { nm: String(pedra.nm).trim(), cat: pedra.cat || '', pr: n(pedra.pr) } : null,
    cuba: cuba ? { nm: String(cuba.nm).trim(), dim: cuba.dim || '', pr: n(cuba.pr) } : null, cubaOp,
    acessorios: acess.map(x => ({ nm: String(x.nm).trim(), pr: n(x.pr) })) };
  await env.HR_KV.put('site:lead:' + protocolo, JSON.stringify(lead), { expirationTtl: 60 * 86400 });
  // resumo (o mesmo texto vai para o dono e para a memória da conversa do cliente)
  const linhas = [
    `Ambiente: ${SITE_AMB[amb]}`,
    lead.pedra ? `Pedra: ${lead.pedra.nm}${lead.pedra.pr ? ' (R$ ' + reais(lead.pedra.pr) + '/m²)' : ''}` : '',
    lead.cuba ? `Cuba: ${lead.cuba.nm}${lead.cuba.dim ? ' ' + lead.cuba.dim : ''}${lead.cuba.pr ? ' (R$ ' + reais(lead.cuba.pr) + ')' : ''}` : (cubaOp ? `Cuba: ${cubaOp.toLowerCase()}` : ''),
    lead.acessorios.length ? `Acessórios: ${lead.acessorios.map(x => x.nm + (x.pr ? ' (R$ ' + reais(x.pr) + ')' : '')).join(', ')}` : '',
    medidas ? `Medidas: ${medidas}` : '',
    obs ? `Observação: ${obs}` : '', cidade ? `Cidade: ${cidade}` : '',
  ].filter(Boolean);
  // conversa do cliente já começa com as escolhas: a secretária não pergunta de novo
  try {
    let c = null; try { c = JSON.parse((await env.HR_KV.get('ca:' + tel)) || 'null'); } catch (_) {}
    if (!c || c.concluido) c = { dados: {}, hist: (c && c.hist ? c.hist : []).slice(-4), nomeOrigem: 'salvo' };
    const d = c.dados = c.dados || {};
    d.nome = d.nome || nome;
    if (INTERESSES[amb]) d.interesse = amb;
    if (lead.pedra) d.cor = lead.pedra.nm;
    if (AMB_BANCADA.includes(amb)) {
      const bc = d.bancada = d.bancada || {};
      if (lead.cuba) { bc.cuba = 'sim'; bc.cuba_modelo = (lead.cuba.nm + ' ' + (lead.cuba.dim || '')).trim().slice(0, 120); }
      else if (/nao quero/i.test(normaliza(cubaOp))) bc.cuba = 'nao';
      else if (/ja tenho/i.test(normaliza(cubaOp))) { bc.cuba = 'sim'; bc.cuba_modelo = 'cuba do próprio cliente'; }
      if (lead.acessorios.length) { bc.acessorios = 'sim'; bc.acessorios_quais = lead.acessorios.map(x => x.nm).join(', ').slice(0, 160); }
    }
    if (medidas) d.detalhe = [d.detalhe, 'Medidas informadas no site: ' + medidas].filter(Boolean).join(' | ').slice(0, 500);
    c.site = protocolo; c.origem = c.origem || 'site';
    c.hist = (c.hist || []).concat([{ role: 'assistant', content: `[Anotação: o cliente montou o projeto no site da HR — protocolo ${protocolo}. Escolhas dele (não pergunte de novo; confirme e siga para o que falta, como medidas e visita):]\n${linhas.join('\n')}` }]).slice(-CLIENTE_HIST_MAX);
    c.ultimaEm = Date.now();
    await env.HR_KV.put('ca:' + tel, JSON.stringify(c), { expirationTtl: CLIENTE_TTL });
  } catch (e) { console.log('[SITE] conversa do cliente:', e.message); }
  // aviso ao dono
  const totAcess = lead.acessorios.reduce((s2, x) => s2 + x.pr, 0) + (lead.cuba ? lead.cuba.pr : 0);
  try {
    await notificarDono(env, Date.now(), `*Novo projeto pelo site* — ${protocolo}\n*${nome}*${cidade ? ' (' + cidade + ')' : ''}\n${linhas.filter(l => !/^Cidade:/.test(l)).join('\n')}${totAcess ? `\nCuba + acessórios: R$ ${reais(totAcess)}` : ''}\n\nJá está no app, em *Orçamento → Projetos do site*: é só tocar em "Montar orçamento".\nwa.me/${tel}`);
  } catch (e) { console.log('[SITE] aviso ao dono:', e.message); }
  // veio pelo link do WhatsApp: o bot confirma na própria conversa (a janela de 24 h está aberta)
  let avisado = false;
  if (doLink) {
    try { await enviar(env, tel, `${nomeDeTratamento(nome) || 'Olá'}, recebi o seu projeto (${lead.pedra ? lead.pedra.nm : SITE_AMB[amb]}). O responsável vai montar o orçamento completo e eu te envio aqui mesmo. Se tiver as medidas ou fotos do local, pode mandar por aqui.`); avisado = true; } catch (e) { console.log('[SITE] confirmação ao cliente:', e.message); }
  }
  const bot = String(env.WHATSAPP_PUBLICO || '').replace(/\D/g, '') || await pontoBotNumero(env);
  const msg = `Olá! Sou ${nome.split(' ')[0]} e montei o meu projeto no site (protocolo ${protocolo}). ${lead.pedra ? 'Escolhi a pedra ' + lead.pedra.nm + '. ' : ''}Gostaria de receber o orçamento.`;
  return resp({ ok: true, protocolo, avisado, wa: bot ? (avisado ? `https://wa.me/${bot}` : `https://wa.me/${bot}?text=${encodeURIComponent(msg)}`) : '' });
}

async function rotaPortfolio(req, env, ctx, url) {
  const cab = { 'Access-Control-Allow-Origin': '*' };
  const p = url.pathname.replace(/\/+$/, '');
  if (p === '/portfolio/pedido') return sitePedido(req, env, ctx); // v50: o cliente montou o projeto no site
  if (req.method !== 'GET') return new Response('Método não permitido', { status: 405, headers: cab });
  if (p === '/portfolio/catalogo') return siteCatalogo(env, ctx, url);
  if (p.startsWith('/portfolio/img/')) return siteImagem(env, ctx, url, p);
  if (p === '/portfolio') {
    return new Response(PORTFOLIO_HTML, { headers: { ...cab, 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'public, max-age=300' } });
  }
  const cache = caches.default, chave = new Request(url.toString(), { method: 'GET' });
  const emCache = await cache.match(chave);
  if (emCache) return emCache;
  let resp;
  if (p === '/portfolio/pedras') {
    const lista = await lerPortfolio(env), porNome = new Map();
    const pontos = i => (i.origem === 'app' ? (i.semFoto ? 1 : 3) : 2);
    for (const i of lista) {
      if (!i || i.tipo !== 'pedra' || !i.nome) continue;
      const k = normaliza(i.nome), atual = porNome.get(k);
      if (!atual || pontos(i) > pontos(atual)) porNome.set(k, i);
    }
    const preco = String(env.PORTFOLIO_PRECO ?? '1') !== '0'; // v33: valor do m² aparece (PORTFOLIO_PRECO=0 esconde)
    // v33: mais escolhidas = soma das escolhas em todos os pedidos (cfg:pop), mais as fixadas pelo dono em PORTFOLIO_DESTAQUES
    let popT = {}, usos = {};
    try {
      const pop = JSON.parse((await env.HR_KV.get('cfg:pop')) || '{}') || {};
      const ROT = { soleira: 'soleiras', peitoril: 'peitoris', cozinha: 'cozinhas', banheiro: 'banheiros', lavabo: 'lavabos', area_servico: 'áreas de serviço', varanda: 'varandas', escada: 'escadas', piso: 'pisos', tumulo: 'túmulos' };
      for (const [amb, m] of Object.entries(pop)) for (const [nome, n] of Object.entries(m || {})) {
        const k = normaliza(nome); popT[k] = (popT[k] || 0) + (Number(n) || 0);
        if (ROT[amb] && n >= 2) (usos[k] = usos[k] || []).push([ROT[amb], Number(n)]);
      }
    } catch (_) {}
    const fixas = String(env.PORTFOLIO_DESTAQUES || '').split(/[,;\n]/).map(x => normaliza(x)).filter(Boolean);
    for (const [k, i] of porNome) { // foto manual sem dados: completa com o cadastro do app (igual ao cartão do bot)
      if (i.origem === 'app') continue;
      const app = lista.find(x => x && x.origem === 'app' && x.tipo === 'pedra' && normaliza(x.nome) === k);
      if (app) porNome.set(k, { ...i, tp: i.tp || app.tp, acab: i.acab || app.acab, desc: i.desc || app.desc, preco: i.preco || app.preco });
    }
    const pedras = [...porNome.values()].map(i => ({
      id: i.id, nome: String(i.nome).slice(0, 60), cat: String(i.tp || '').slice(0, 40), acab: String(i.acab || '').slice(0, 40),
      desc: String(i.desc || '').slice(0, 700), foto: !i.semFoto, ...(preco && Number(i.preco) > 0 ? { preco: Number(i.preco) } : {}),
      pop: (popT[normaliza(i.nome)] || 0) + (fixas.includes(normaliza(i.nome)) ? 100000 - fixas.indexOf(normaliza(i.nome)) : 0),
      usos: (usos[normaliza(i.nome)] || []).sort((x, y) => y[1] - x[1]).slice(0, 2).map(x => x[0]),
    })).sort((a, b) => (b.foto - a.foto) || a.nome.localeCompare(b.nome, 'pt-BR'));
    pedras.filter(x => x.foto && x.pop > 0).sort((a, b) => b.pop - a.pop).slice(0, 8).forEach((x, n) => { x.rank = n + 1; });
    resp = new Response(JSON.stringify({
      empresa: env.EMPRESA || 'HR Mármores e Granitos', logo: /^https:\/\//.test(String(env.LOGO_URL || '')) ? env.LOGO_URL : '',
      whatsapp: String(env.WHATSAPP_PUBLICO || '').replace(/\D/g, ''), pedras,
    }), { headers: { ...cab, 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'public, max-age=120' } });
  } else if (p.startsWith('/portfolio/foto/')) {
    const id = decodeURIComponent(p.slice('/portfolio/foto/'.length));
    const it = (await lerPortfolio(env)).find(x => x && x.id === id && x.tipo === 'pedra');
    const buf = it && !it.semFoto ? await env.HR_KV.get('pf:img:' + id, 'arrayBuffer') : null;
    if (!buf) return new Response('Sem foto', { status: 404, headers: cab });
    resp = new Response(buf, { headers: { ...cab, 'Content-Type': it.mime || 'image/jpeg', 'Cache-Control': 'public, max-age=3600' } });
  } else {
    return new Response('Não encontrado', { status: 404, headers: cab });
  }
  ctx.waitUntil(cache.put(chave, resp.clone()));
  return resp;
}

// v19: avisa o dono, uma vez só por pedido, quando o app demora a calcular o valor ou a gerar o PDF (limite padrão: 5 min).
// Não grava o pedido (só uma marca separada no KV), para não sobrescrever o que o app está atualizando.
async function alertaAppParado(env) {
  const LIM = Math.max(1, Number(env.APP_PARADO_MIN) || 5) * 60 * 1000, H = 3600 * 1000;
  const agora = Date.now();
  const lista = await env.HR_KV.list({ prefix: 'ped:' });
  for (const k of lista.keys.slice(-150)) {
    let x = null; try { x = JSON.parse((await env.HR_KV.get(k.name)) || 'null'); } catch (_) {}
    if (!x || x.status !== 'pendente' || !x.numero) continue;
    const criado = x.id > 1e14 ? Math.floor(x.id / 10) : x.id;
    const gerar = x.fase === 'gerar';
    const idade = agora - (gerar ? (x.valorConfirmadoEm || x.prazoEm || criado) : criado);
    if (idade < LIM || idade > 24 * H) continue;
    const marca = 'alertaapp:' + x.id + ':' + (gerar ? 'gerar' : 'calcular');
    if (await env.HR_KV.get(marca)) continue;
    await env.HR_KV.put(marca, '1', { expirationTtl: 2 * 24 * 3600 }); // marca ANTES de enviar: no máximo um aviso por etapa
    const min = Math.round(idade / 60000);
    const o = gerar ? 'o app ainda não gerou o PDF' : 'o app ainda não calculou o valor';
    await notificarDono(env, agora, `*${x.nome || 'Cliente'}* está esperando há ${min} min: ${o}. Confira se o app está aberto no computador.\nwa.me/${x.numero}`)
      .catch(e => falhou(env, 'alertaAppParado: aviso', e));
  }
}

export default {
  async scheduled(event, env, ctx) {
    env = comKV(env); // v24: conversas gravadas com metadados (ver "ECONOMIA DO KV")
    configurarRegras(env); // v27: limite de peças e pingadeira
    // v19: gatilho opcional de 5 em 5 min só para o aviso de app parado (defina CRON_ALERTA_APP com o mesmo texto do gatilho criado no Cloudflare)
    if (env.CRON_ALERTA_APP && event && event.cron === env.CRON_ALERTA_APP && event.cron !== (env.CRON_AVALIACAO || '*/15 * * * *')) {
      ctx.waitUntil(alertaAppParado(env).catch(e => falhou(env, 'rotina: app parado', e)));
      return;
    }
    // a partir da hora do fechamento (17h de Bahia) o agendamento convoca o fechamento; antes disso roda a rotina da manhã
    ctx.waitUntil(pedirAvaliacoes(env));
    ctx.waitUntil(redeSegurancaMP(env).catch(e => falhou(env, 'rotina: rede de segurança MP', e))); // acha pagamentos aprovados cujo aviso não chegou (a cada REDE_MP_HORAS)
    ctx.waitUntil(enviarAvaliacoesGoogle(env).catch(e => falhou(env, 'rotina: avaliação Google', e)));
    ctx.waitUntil(enviarPosInstalacao(env).catch(e => falhou(env, 'rotina: pós-instalação', e)));
    ctx.waitUntil(recRotina(env).catch(e => falhou(env, 'rotina: a receber', e))); // Etapa 72: cobrança dos clientes do "A Receber" do app
    ctx.waitUntil(cobrancasD1Rotina(env).catch(e => falhou(env, 'rotina: cobranças D1', e))); // inerte sem o binding HR_DB
    ctx.waitUntil(cobrancasAgendadasRotina(env).catch(e => falhou(env, 'rotina: cobranças agendadas', e))); // "manda amanhã às 7h"
    ctx.waitUntil(qrExpirar(env).catch(e => falhou(env, 'rotina: QR code', e)));
    ctx.waitUntil(pontoRotina(env).catch(e => falhou(env, 'rotina: ponto', e))); // v34: saída esquecida
    ctx.waitUntil(agendaEquipeDiaria(env).catch(e => falhou(env, 'rotina: agenda da equipe', e))); // v63r
    ctx.waitUntil(followupOrcamentosDiario(env).catch(e => falhou(env, 'rotina: orçamentos parados', e))); // v63s
    ctx.waitUntil(dicaDoDia(env).catch(e => falhou(env, 'rotina: dica do dia', e))); // v63t
    ctx.waitUntil(igRenovarToken(env).catch(e => falhou(env, 'rotina: token do Instagram', e))); // v64
    ctx.waitUntil(igRotina(env).catch(e => falhou(env, 'rotina: Instagram', e))); // v65
    ctx.waitUntil(igAnaliseRotina(env).catch(e => falhou(env, 'rotina: análise do Instagram', e))); // v68
    ctx.waitUntil(estRotina(env).catch(e => falhou(env, 'rotina: estúdio de posts', e))); // v69
    ctx.waitUntil((async () => { // em fila, não em paralelo: todas regravam o pedido inteiro e uma sobrescrevia a outra
      for (const [nome, fn] of [['lembretes', lembretesDeValor], ['seguimento', seguimentoValor], ['prazo do Pix', lembretesPixCurto], ['lembrete Pix', lembretesDePix], ['lembrete restante', lembretesRestante], ['bot no lugar do app', pedidosNoBotRotina], ['app parado', alertaAppParado], ['pronto no dia', prontoNoDiaRotina]]) {
        try { await fn(env); } catch (e) { await falhou(env, 'rotina: ' + nome, e); }
      }
    })());
    ctx.waitUntil(lembretesVisitaDono(env).catch(e => falhou(env, 'rotina: lembrete de visita ao dono', e)));
    ctx.waitUntil(lembretesVisitaCliente(env).catch(e => falhou(env, 'rotina: lembrete de visita ao cliente', e))); // v51
    ctx.waitUntil(alertasDePrazoDiario(env).catch(e => falhou(env, 'rotina: alerta de prazo', e)));
    ctx.waitUntil(conciliacaoDiaria(env).catch(e => falhou(env, 'rotina: conciliação', e)));
    ctx.waitUntil(extratoMPDiario(env));
    ctx.waitUntil(fechamentoSemanalMPX(env).catch(e => falhou(env, 'rotina: fechamento semanal', e)));
    ctx.waitUntil(conferenciaDiaria(env).catch(e => falhou(env, 'rotina: conferência', e)));
    ctx.waitUntil(auditoriaDiaria(env).catch(e => falhou(env, 'rotina: auditoria', e)));
    if (event && event.cron && event.cron === (env.CRON_AVALIACAO || '*/15 * * * *')) return; // gatilho só da nota: não repete as rotinas do dono
    const hf = Number(env.FECHAMENTO_HORA) || 17;
    if (agoraBahia().min >= hf * 60) ctx.waitUntil(convocarFechamento(env));
    else { ctx.waitUntil(rotinaDiaria(env)); ctx.waitUntil(cobrarFechamentoAtrasado(env).catch(e => falhou(env, 'rotina: fechamento atrasado', e))); }
  },

  async fetch(req, env, ctx) {
    env = comKV(env); // v24: conversas gravadas com metadados (ver "ECONOMIA DO KV")
    configurarRegras(env); // v27: limite de peças e pingadeira
    if (ctx && ctx.waitUntil) try { env._waitUntil = p => ctx.waitUntil(p); } catch (_) {} // v63k: tarefas depois da resposta
    const url = new URL(req.url);

    if (req.method === 'OPTIONS') return new Response(null, { status: 204, headers: CORS });
    if (url.pathname.startsWith('/bot/')) return rotaBot(req, env, url);
    if (url.pathname === '/mp/webhook') return rotaMercadoPago(req, env, ctx, url);
    if (url.pathname === '/portfolio' || url.pathname.startsWith('/portfolio/')) return rotaPortfolio(req, env, ctx, url);
    if (url.pathname === '/ponto' || url.pathname.startsWith('/ponto/')) return rotaPonto(req, env, ctx, url); // v34: HR Ponto
    if (url.pathname.startsWith('/pagar/')) return rotaPagar(req, env, url); // v49: página de pagamento da HR
    if (url.pathname.startsWith('/m/')) return rotaMidia(req, env, url); // v69: mídia dos posts (Instagram e prévias)
    if (url.pathname.startsWith('/editor/')) return rotaEditor(req, comKV(env), url); // v69: editor de vídeo do computador

    if (url.pathname !== '/webhook') {
      return new Response('HR Mármores — bot online', { status: 200 });
    }

    // Verificação inicial feita pela Meta ao salvar o webhook
    if (req.method === 'GET') {
      const ok = url.searchParams.get('hub.mode') === 'subscribe'
        && env.VERIFY_TOKEN
        && url.searchParams.get('hub.verify_token') === env.VERIFY_TOKEN;
      return ok
        ? new Response(url.searchParams.get('hub.challenge') || '', { status: 200 })
        : new Response('Forbidden', { status: 403 });
    }

    if (req.method === 'POST') {
      const raw = await req.text();
      let payload = null;
      try { payload = JSON.parse(raw); } catch (_) { payload = null; }
      if (payload && payload.object === 'instagram') { // v64: avisos do Instagram (assinados com a chave do app do Instagram)
        const sig = req.headers.get('x-hub-signature-256');
        if (!(await assinaturaValida(raw, sig, await igSegredo(env))) && !(await assinaturaValida(raw, sig, env.APP_SECRET))) return new Response('Assinatura inválida', { status: 401 });
        ctx.waitUntil(igTratarPayload(env, payload));
        return new Response('ok', { status: 200 });
      }
      if (!(await assinaturaValida(raw, req.headers.get('x-hub-signature-256'), env.APP_SECRET))) {
        return new Response('Assinatura inválida', { status: 401 });
      }
      if (!payload) return new Response('ok', { status: 200 });
      if (globalThis.__cfgSelf !== url.origin) { // v24: guarda o endereço do Worker (base dos links de pagamento) só quando muda
        globalThis.__cfgSelf = url.origin;
        ctx.waitUntil((async () => { if ((await env.HR_KV.get('cfg:self')) !== url.origin) await env.HR_KV.put('cfg:self', url.origin); })().catch(() => { globalThis.__cfgSelf = ''; }));
      }
      ctx.waitUntil(tratarPayload(env, payload)); // responde 200 rápido; processa em segundo plano
      return new Response('ok', { status: 200 });
    }

    return new Response('Método não permitido', { status: 405 });
  },
};



